    #[test]
    fn tier3_codegen_http_without_prometheus_does_not_emit_prelude_or_dep() {
        // v0.13.1 — refined gating for the "Smoke gating of emitted
        // deps" debt. HTTP programs WITHOUT literal `@server(prometheus=true)`
        // do NOT bring in PROMETHEUS_PRELUDE or the
        // `metrics-exporter-prometheus` dep. Previously (original Tier3) the
        // prelude was always emitted with has_http to enable the
        // `FITZ_PROMETHEUS=1` env var path at runtime, but the
        // compile_e2e smoke paid the cold-compile of the dep in ~290
        // examples. Trade-off: the env var override stops
        // working — production deployments declare Prometheus
        // in code.
        let src = "@get(\"/x\")\nfn h() -> Str => \"ok\"\n";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        assert!(
            !code.contains("__FITZ_PROMETHEUS_HANDLE"),
            "should NOT emit static __FITZ_PROMETHEUS_HANDLE without opt-in: {}",
            code
        );
        assert!(
            !code.contains("fn __fitz_init_prometheus("),
            "should NOT emit helper __fitz_init_prometheus without opt-in: {}",
            code
        );
        assert!(
            !code.contains("__fitz_prometheus_route"),
            "should NOT emit __fitz_prometheus_route without opt-in: {}",
            code
        );
        // Emitted Cargo.toml (uses_prometheus_export=false) does NOT include the dep.
        // Args: (stem, has_http, uses_async, uses_python, uses_auth,
        // uses_ws, uses_jobs, uses_logging, uses_trace_metric,
        // uses_db, uses_fitz_value, uses_date_or_uuid,
        // uses_prometheus_export).
        let cargo = cargo_toml_for(
            "foo", true, false, false, false, false, false, true, false, false, false, false,
            false, false, false, false,
        );
        assert!(
            !cargo.contains("metrics-exporter-prometheus"),
            "Cargo.toml must NOT include metrics-exporter-prometheus without opt-in: {}",
            cargo
        );
    }

    #[test]
    fn tier3_codegen_http_with_prometheus_true_emits_prelude_and_dep() {
        // v0.13.1 — refined gating. With literal `@server(prometheus=true)`
        // codegen emits the entire Prometheus prelude
        // (handle + init + route) + the `metrics-exporter-prometheus` dep
        // in Cargo.toml. The compile-time flag triggers
        // `__fitz_init_prometheus(true)` which installs the recorder at
        // boot; `__fitz_prometheus_route()` mounts `/metrics`
        // on the axum Router.
        let src =
            "@server(3000, prometheus=true)\nfn cfg() => 0\n@get(\"/x\")\nfn h() -> Str => \"ok\"\n";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        assert!(
            code.contains("__FITZ_PROMETHEUS_HANDLE"),
            "expected static __FITZ_PROMETHEUS_HANDLE: {}",
            code
        );
        assert!(
            code.contains("fn __fitz_init_prometheus(compile_time_enabled: bool)"),
            "expected helper __fitz_init_prometheus: {}",
            code
        );
        assert!(
            code.contains("__fitz_init_prometheus(true);"),
            "expected init call with true: {}",
            code
        );
        assert!(
            code.contains(".merge(__fitz_prometheus_route())"),
            "expected .merge(__fitz_prometheus_route()) in the Router: {}",
            code
        );
        // Emitted Cargo.toml (uses_prometheus_export=true) includes the dep.
        // Args: (stem, has_http, uses_async, uses_python, uses_auth,
        // uses_ws, uses_jobs, uses_logging, uses_trace_metric,
        // uses_db, uses_fitz_value, uses_date_or_uuid,
        // uses_prometheus_export).
        let cargo = cargo_toml_for(
            "foo", true, false, false, false, false, false, true, false, false, false, false, true,
            false, false, false,
        );
        assert!(
            cargo.contains("metrics-exporter-prometheus"),
            "Cargo.toml HTTP+Prometheus must include metrics-exporter-prometheus: {}",
            cargo
        );
    }

