    #[test]
    fn v019_4_http_request_headers_map_emits_snapshot_binding_for_send() {
        // 2026-06-23 (deuda 🔴 URGENTE de v0.19.3 cerrada): `http.request`
        // con `headers` Map literal debe emitir un binding intermedio
        // `let __headers_snap: Vec<(String, String)> = ... .lock().unwrap().clone();`
        // que dropea el `MutexGuard` ANTES del `.await` del request, para
        // que el `Future` sea `Send` cuando el caller es `spawn(async fn)`.
        // El patrón viejo `(...).lock().unwrap().clone()` inline mantenía
        // el guard vivo cross-await. Análogo al fix de v0.18.1 para
        // `for x in List<Str>` adentro de `@cron`.
        let src = "async fn call(u: Str, key: Str) -> Result<Int> {\n\
                       let r = http.request({\n\
                           \"method\": \"POST\",\n\
                           \"url\": u,\n\
                           \"headers\": {\n\
                               \"Authorization\": \"Bearer x\",\n\
                               \"Content-Type\": \"application/json\"\n\
                           }\n\
                       }).await?\n\
                       return Ok(r.status)\n\
                   }\n";
        let code = gen(src).expect("codegen ok");
        assert!(
            code.contains("let __headers_snap: Vec<(String, String)>"),
            "expected `let __headers_snap: Vec<(String, String)>` binding that drops the MutexGuard before the await; \
             without it the future is not Send and `spawn(...)` rejects.\n\
             Generated code did not contain the binding."
        );
        // Regression: the OLD pattern `(({...}).lock().unwrap().clone())`
        // appearing INSIDE the `__FitzHttpRequestOpts { headers: ... }`
        // callsite field would mean we kept the guard cross-await.
        // Anchor to the struct literal callsite (NOT the struct
        // declaration in the prelude — both contain `headers:`).
        let callsite_at = code
            .find("__FitzHttpRequestOpts { method:")
            .expect("__FitzHttpRequestOpts callsite present");
        let after = &code[callsite_at..];
        // The struct literal is on a single line; first 600 chars are
        // enough to cover all fields.
        let snippet = &after[..after.len().min(600)];
        assert!(
            snippet.contains("headers: { let __headers_snap"),
            "the `headers` field of `__FitzHttpRequestOpts {{ ... }}` callsite must use the \
             `__headers_snap` block binding (the guard must be dropped before the await); \
             snippet was:\n{}",
            snippet
        );
    }

    #[test]
    fn http_client_codegen_unknown_method_errors_with_supported_list() {
        let src = "async fn bad(u: Str) -> Result<Int> {\n\
                       let r = http.fetch(u).await?\n\
                       return Ok(r.status)\n\
                   }\n";
        let err = gen(src).expect_err("expected codegen error on http.fetch");
        assert!(
            err.message
                .contains("get, head, post, put, delete, request"),
            "expected supported-methods list, got: {}",
            err.message
        );
    }

    #[test]
    fn http_client_codegen_get_wrong_arity_errors() {
        let src = "async fn bad() -> Result<Int> {\n\
                       let r = http.get(\"a\", \"b\").await?\n\
                       return Ok(r.status)\n\
                   }\n";
        let err = gen(src).expect_err("expected codegen error on wrong arity");
        assert!(
            err.message.contains("1 argument"),
            "expected arity-1 message, got: {}",
            err.message
        );
    }

    #[test]
    fn http_client_codegen_no_calls_does_not_emit_prelude() {
        // Sanity: pure CLI program without `http.X` should NOT emit the
        // HTTP client prelude (no reqwest reference in main.rs).
        let src = "fn double(n: Int) -> Int => n * 2\n";
        let code = gen(src).expect("codegen ok");
        assert!(
            !code.contains("HttpClientResponse"),
            "should not emit HttpClientResponse in a program without http.X"
        );
        assert!(
            !code.contains("__FITZ_HTTP_CLIENT"),
            "should not emit the LazyLock client without http.X"
        );
        assert!(
            !code.contains("__fitz_http_get"),
            "should not emit any __fitz_http_* helper without http.X"
        );
    }

    #[test]
    fn http_client_codegen_emits_to_fitz_json_when_has_http() {
        // When the program has BOTH http.X(...) and HTTP handlers,
        // the integration prelude emits `__ToFitzJson`/`__FromFitzJson`
        // impls for HttpClientResponseData so handlers can return the
        // response.
        let src = "async fn fetch(u: Str) -> Result<Int> {\n\
                       let r = http.get(u).await?\n\
                       return Ok(r.status)\n\
                   }\n\
                   @get(\"/ping\")\n\
                   async fn ping() -> Result<Int> => fetch(\"http://x\").await\n";
        let code = gen(src).expect("codegen ok");
        assert!(
            code.contains("impl __ToFitzJson for HttpClientResponseData"),
            "expected __ToFitzJson impl when has_http && uses_http_client"
        );
        assert!(
            code.contains("impl __FromFitzJson for HttpClientResponseData"),
            "expected __FromFitzJson impl when has_http && uses_http_client"
        );
    }

    #[test]
    fn http_client_codegen_skips_json_impls_for_pure_cli() {
        // Pure CLI without HTTP server: only the HTTP client prelude
        // is emitted, not the JSON integration impls (which depend on
        // serde_json in scope, only present when has_http).
        let src = "async fn fetch(u: Str) -> Result<Int> {\n\
                       let r = http.get(u).await?\n\
                       return Ok(r.status)\n\
                   }\n";
        let code = gen(src).expect("codegen ok");
        assert!(
            code.contains("struct HttpClientResponseData"),
            "expected HTTP client prelude in pure-CLI program with http.X"
        );
        assert!(
            !code.contains("impl __ToFitzJson for HttpClientResponseData"),
            "should NOT emit __ToFitzJson without HTTP server (no serde_json in scope)"
        );
    }

    #[test]
    fn iter2b_codegen_cli_log_emits_stub_no_op_of_emit_to_otel() {
        // Phase 12.3.iter2.b — pure CLI programs with `log.*` (without
        // HTTP) do NOT have OTEL_PRELUDE → LOGGING_PRELUDE includes the
        // no-op stub `__fitz_emit_log_to_otel` so that `__fitz_log_emit`
        // can call it without breaking the compile. The stub emits nothing
        // (logs go only to stderr).
        let src = "log.info(\"hello\")";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        assert!(
            code.contains("Without OTEL_PRELUDE: no-op stub"),
            "expected no-op stub of __fitz_emit_log_to_otel for CLI: {}",
            code
        );
        assert!(
            code.contains("fn __fitz_emit_log_to_otel(_level_str: &str"),
            "expected signature of the no-op stub: {}",
            code
        );
        assert!(
            !code.contains("opentelemetry_otlp::LogExporter::builder"),
            "CLI without HTTP must NOT emit the LogExporter init: {}",
            code
        );
    }

    #[test]
    fn iter2b_codegen_http_log_emits_real_logger_provider_and_log_exporter() {
        // Phase 12.3.iter2.b — programs with HTTP + log.* include
        // OTEL_PRELUDE with real LogExporter + LoggerProvider. The
        // no-op stub is NOT emitted (there is a real impl). Emitted
        // Cargo.toml requests feature `logs` in the three OTel crates.
        let src = "log.info(\"hi\")\n@get(\"/x\")\nfn h() -> Str => \"ok\"\n";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // The no-op stub must NOT be present.
        assert!(
            !code.contains("Without OTEL_PRELUDE: no-op stub"),
            "HTTP + log must use real impl, not stub: {}",
            code
        );
        // LogExporter in the OTel init.
        assert!(
            code.contains("opentelemetry_otlp::LogExporter::builder"),
            "expected LogExporter init in OTEL_PRELUDE: {}",
            code
        );
        // Global LoggerProvider static.
        assert!(
            code.contains("__FITZ_OTEL_LOGGER_PROVIDER"),
            "expected __FITZ_OTEL_LOGGER_PROVIDER static: {}",
            code
        );
        // Real impl of the helper with LogRecord + trace_context.
        assert!(
            code.contains("fn __fitz_emit_log_to_otel(level_str: &str"),
            "expected real impl of __fitz_emit_log_to_otel: {}",
            code
        );
        assert!(
            code.contains("record.set_trace_context"),
            "expected set_trace_context for correlation: {}",
            code
        );
        // Cargo.toml must request feature `logs` in the three OTel crates.
        // Args: (stem, has_http, uses_async, uses_python, uses_auth,
        // uses_ws, uses_jobs, uses_logging, uses_db, uses_fitz_value,
        // uses_date_or_uuid). HTTP + logging active trigger the block
        // that emits the OTel + metrics + uuid + chrono + tracing deps.
        let cargo = cargo_toml_for(
            "foo", true, false, false, false, false, false, true, false, false, false, false,
            false, false, false, false,
        );
        assert!(
            cargo.contains("opentelemetry-otlp"),
            "Cargo.toml for HTTP+log must include opentelemetry-otlp: {}",
            cargo
        );
        assert!(
            cargo.contains("\"logs\""),
            "Cargo.toml must request feature `logs` in the OTel crates: {}",
            cargo
        );
    }

    #[test]
    fn iter2a_codegen_http_emits_with_ids_branch_derived_from_otel_span() {
        // Phase 12.3.iter2.a — when there is an HTTP handler WITH
        // observability active, the codegen wrapper must emit the
        // pattern "open OTel span first, derive SpanContext with
        // `with_ids` from its IDs". Without OTel active at runtime, the
        // alternative branch (`new_root()`) fires and everything keeps
        // working as before (bit-for-bit parity with `dispatch_request`
        // of the interpreter).
        //
        // OTel deps gating (2026-08-07) — observability in `fitz build`
        // is now OPT-IN via `log.X(...)`; the handler calls `log.info`
        // so `uses_logging == true` and the wrapper emits the block.
        let src = "@get(\"/hello\")\nfn h() -> Str {\n  log.info(\"hit\")\n  return \"ok\"\n}\n";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // The `with_ids` method must be defined in the prelude.
        assert!(
            code.contains("pub fn with_ids(trace_id: String, span_id: String)"),
            "expected __FitzSpanContext::with_ids in the prelude: {}",
            code
        );
        // The wrapper must open the OTel span BEFORE the SpanContext.
        let otel_idx = code
            .find("let mut __otel_span = if __fitz_otel_is_enabled()")
            .expect("expected opening of __otel_span in the wrapper");
        let span_ctx_idx = code
            .find("let __fitz_span_ctx = if let Some(span) = __otel_span.as_ref()")
            .expect("expected derivation of __fitz_span_ctx from __otel_span");
        assert!(
            otel_idx < span_ctx_idx,
            "the OTel span must be opened BEFORE deriving the SpanContext: \
             otel_idx={} span_ctx_idx={}",
            otel_idx,
            span_ctx_idx
        );
        // Alternative branch: without OTel active, fallback to new_root.
        assert!(
            code.contains("__FitzSpanContext::new_root()"),
            "expected fallback __FitzSpanContext::new_root() for !is_otel_enabled: {}",
            code
        );
        // Explicit use of `sctx.trace_id().to_string()` and
        // `sctx.span_id().to_string()` to build the SpanContext.
        assert!(
            code.contains("sctx.trace_id().to_string()")
                && code.contains("sctx.span_id().to_string()"),
            "expected derivation of trace_id/span_id from sctx: {}",
            code
        );
    }

    #[test]
