    // ---- AST-based test helpers (T1 post-5b) ---------------------------
    //
    // These helpers parse the Rust generated by the codegen with `syn` and
    // allow asserting on the AST structure instead of matching literal
    // strings of the output. The advantage is that cosmetic changes
    // of the codegen (spaces, numeric suffixes, parenthesis grouping)
    // do not break the tests — only real structural changes do.
    //
    // Convention: the helpers take `&str` as generated code and
    // return `syn::File`/`&Item*`/`String` as appropriate. To
    // stringify sub-trees we use `quote::ToTokens::to_token_stream()`
    // and normalize whitespace, so comparisons are robust.
    //
    // `#[allow(dead_code)]`: the migration of tests to AST-based is
    // incremental; some helpers may remain unused until more tests
    // are migrated.
    #[allow(dead_code)]
    mod ast_test {
        use quote::ToTokens;
        use syn::{File, Item, ItemFn, ItemImpl, ItemStruct, ItemType, Local, Pat, Stmt};

        /// Parses the generated Rust. If syn cannot parse it, panics
        /// with the full code in the message (which is itself a signal:
        /// the codegen is emitting invalid Rust).
        pub fn parse(code: &str) -> File {
            syn::parse_file(code).unwrap_or_else(|e| {
                panic!(
                    "syn could not parse the generated Rust: {}\n\nCode:\n{}",
                    e, code
                )
            })
        }

        /// Stringifies any `ToTokens` node with whitespace
        /// normalized to a single space between tokens. Robust against
        /// cosmetic format changes.
        pub fn ts<T: ToTokens>(node: &T) -> String {
            let raw = node.to_token_stream().to_string();
            raw.split_whitespace().collect::<Vec<_>>().join(" ")
        }

        pub fn find_item_fn<'a>(file: &'a File, name: &str) -> Option<&'a ItemFn> {
            file.items.iter().find_map(|i| match i {
                Item::Fn(f) if f.sig.ident == name => Some(f),
                _ => None,
            })
        }

        pub fn find_item_struct<'a>(file: &'a File, name: &str) -> Option<&'a ItemStruct> {
            file.items.iter().find_map(|i| match i {
                Item::Struct(s) if s.ident == name => Some(s),
                _ => None,
            })
        }

        pub fn find_item_type<'a>(file: &'a File, name: &str) -> Option<&'a ItemType> {
            file.items.iter().find_map(|i| match i {
                Item::Type(t) if t.ident == name => Some(t),
                _ => None,
            })
        }

        /// Finds a top-level `static NAME: T = expr;` by name.
        pub fn find_item_static<'a>(file: &'a File, name: &str) -> Option<&'a syn::ItemStatic> {
            file.items.iter().find_map(|i| match i {
                Item::Static(s) if s.ident == name => Some(s),
                _ => None,
            })
        }

        /// Finds a top-level `const NAME: T = expr;` by name.
        pub fn find_item_const<'a>(file: &'a File, name: &str) -> Option<&'a syn::ItemConst> {
            file.items.iter().find_map(|i| match i {
                Item::Const(c) if c.ident == name => Some(c),
                _ => None,
            })
        }

        /// True if the declared visibility is `pub` (not `pub(crate)` nor
        /// private).
        pub fn vis_is_pub(vis: &syn::Visibility) -> bool {
            matches!(vis, syn::Visibility::Public(_))
        }

        /// Looks for an `impl Trait for Type` by trait and type name.
        /// The matching uses `contains` on the tokenized
        /// representation — works for `impl std::fmt::Display for Foo`
        /// (matches with `trait_name = "Display"`).
        pub fn find_impl<'a>(
            file: &'a File,
            trait_name: &str,
            type_name: &str,
        ) -> Option<&'a ItemImpl> {
            file.items.iter().find_map(|i| match i {
                Item::Impl(im) => {
                    let trait_match = im
                        .trait_
                        .as_ref()
                        .is_some_and(|(_, p, _)| ts(p).contains(trait_name));
                    let type_match = ts(&*im.self_ty).contains(type_name);
                    if trait_match && type_match {
                        Some(im)
                    } else {
                        None
                    }
                }
                _ => None,
            })
        }

        /// Returns the stmts of the body of `fn main()`.
        pub fn main_block_stmts(file: &File) -> &[Stmt] {
            let f = find_item_fn(file, "main").expect("did not find fn main in the code");
            &f.block.stmts
        }

        /// Returns the first `let` whose pat binds `name`.
        pub fn find_let<'a>(stmts: &'a [Stmt], name: &str) -> Option<&'a Local> {
            stmts.iter().find_map(|s| match s {
                Stmt::Local(l) if pat_binds(&l.pat, name) => Some(l),
                _ => None,
            })
        }

        /// Counts the `let`s that bind a given name (useful for
        /// validating that a reassignment does NOT emit a new `let`).
        pub fn count_lets(stmts: &[Stmt], name: &str) -> usize {
            stmts
                .iter()
                .filter(|s| matches!(s, Stmt::Local(l) if pat_binds(&l.pat, name)))
                .count()
        }

        fn pat_binds(p: &Pat, name: &str) -> bool {
            match p {
                Pat::Ident(pi) => pi.ident == name,
                Pat::Type(pt) => pat_binds(&pt.pat, name),
                _ => false,
            }
        }

        /// Returns the textual representation of the type of the `let`
        /// (right side of `:`). `None` if the let has no explicit type.
        pub fn local_type(local: &Local) -> Option<String> {
            if let Pat::Type(pt) = &local.pat {
                return Some(ts(&*pt.ty));
            }
            None
        }

        /// Returns the textual representation of the initializer of the
        /// `let` (right side of `=`). `None` if the let has no init.
        pub fn local_init(local: &Local) -> Option<String> {
            local.init.as_ref().map(|li| ts(&*li.expr))
        }

        /// True if the `let` declares the var as `mut`.
        pub fn local_is_mut(local: &Local) -> bool {
            match &local.pat {
                Pat::Ident(pi) => pi.mutability.is_some(),
                Pat::Type(pt) => match pt.pat.as_ref() {
                    Pat::Ident(pi) => pi.mutability.is_some(),
                    _ => false,
                },
                _ => false,
            }
        }

        /// Counts macro invocations (by name of the final segment,
        /// e.g. `println` matches `println!` and `std::println!`).
        pub fn count_macro_calls(stmts: &[Stmt], macro_name: &str) -> usize {
            use syn::visit::Visit;
            struct V<'a> {
                name: &'a str,
                count: usize,
            }
            impl<'a, 'ast> Visit<'ast> for V<'a> {
                fn visit_macro(&mut self, m: &'ast syn::Macro) {
                    if m.path.segments.last().is_some_and(|s| s.ident == self.name) {
                        self.count += 1;
                    }
                    syn::visit::visit_macro(self, m);
                }
            }
            let mut v = V {
                name: macro_name,
                count: 0,
            };
            for s in stmts {
                v.visit_stmt(s);
            }
            v.count
        }

        /// True if at any level of the AST a method call with the
        /// given name appears (e.g. `borrow`, `clone`).
        pub fn contains_method_call(stmts: &[Stmt], method_name: &str) -> bool {
            use syn::visit::Visit;
            struct V<'a> {
                name: &'a str,
                found: bool,
            }
            impl<'a, 'ast> Visit<'ast> for V<'a> {
                fn visit_expr_method_call(&mut self, e: &'ast syn::ExprMethodCall) {
                    if e.method == self.name {
                        self.found = true;
                    }
                    syn::visit::visit_expr_method_call(self, e);
                }
            }
            let mut v = V {
                name: method_name,
                found: false,
            };
            for s in stmts {
                v.visit_stmt(s);
            }
            v.found
        }

        /// Finds the first `for` loop in the stmts (recursive search,
        /// not only top-level).
        pub fn find_for_loop(stmts: &[Stmt]) -> Option<syn::ExprForLoop> {
            use syn::visit::Visit;
            struct V {
                found: Option<syn::ExprForLoop>,
            }
            impl<'ast> Visit<'ast> for V {
                fn visit_expr_for_loop(&mut self, e: &'ast syn::ExprForLoop) {
                    if self.found.is_none() {
                        self.found = Some(e.clone());
                    }
                    syn::visit::visit_expr_for_loop(self, e);
                }
            }
            let mut v = V { found: None };
            for s in stmts {
                v.visit_stmt(s);
            }
            v.found
        }

        /// Finds the first `while` loop in the stmts.
        pub fn find_while_loop(stmts: &[Stmt]) -> Option<syn::ExprWhile> {
            use syn::visit::Visit;
            struct V {
                found: Option<syn::ExprWhile>,
            }
            impl<'ast> Visit<'ast> for V {
                fn visit_expr_while(&mut self, e: &'ast syn::ExprWhile) {
                    if self.found.is_none() {
                        self.found = Some(e.clone());
                    }
                    syn::visit::visit_expr_while(self, e);
                }
            }
            let mut v = V { found: None };
            for s in stmts {
                v.visit_stmt(s);
            }
            v.found
        }

        /// Finds the first `if` (statement or expression) in the stmts.
        pub fn find_if(stmts: &[Stmt]) -> Option<syn::ExprIf> {
            use syn::visit::Visit;
            struct V {
                found: Option<syn::ExprIf>,
            }
            impl<'ast> Visit<'ast> for V {
                fn visit_expr_if(&mut self, e: &'ast syn::ExprIf) {
                    if self.found.is_none() {
                        self.found = Some(e.clone());
                    }
                    syn::visit::visit_expr_if(self, e);
                }
            }
            let mut v = V { found: None };
            for s in stmts {
                v.visit_stmt(s);
            }
            v.found
        }

        /// True if the `fn` signature declares a derive with the
        /// given name (e.g. `PartialEq`).
        pub fn struct_has_derive(s: &ItemStruct, derive: &str) -> bool {
            s.attrs.iter().any(|a| {
                if !a.path().is_ident("derive") {
                    return false;
                }
                let mut found = false;
                let _ = a.parse_nested_meta(|meta| {
                    if meta.path.is_ident(derive) {
                        found = true;
                    }
                    Ok(())
                });
                found
            })
        }

        /// Counts the number of parameters of a `fn`.
        pub fn fn_arity(f: &ItemFn) -> usize {
            f.sig.inputs.len()
        }

        /// Returns the return type of the `fn` as a normalized string,
        /// or `None` if it returns `()`.
        pub fn fn_return_type(f: &ItemFn) -> Option<String> {
            match &f.sig.output {
                syn::ReturnType::Default => None,
                syn::ReturnType::Type(_, ty) => Some(ts(&**ty)),
            }
        }

        /// Returns the parameter types as normalized strings
        /// (omits `self`).
        pub fn fn_param_types(f: &ItemFn) -> Vec<String> {
            f.sig
                .inputs
                .iter()
                .filter_map(|arg| match arg {
                    syn::FnArg::Typed(pt) => Some(ts(&*pt.ty)),
                    _ => None,
                })
                .collect()
        }

        /// Returns the initializer expression of the `let` as
        /// `&syn::Expr`. Useful for structural inspection when
        /// `local_init` (which returns String) is not enough.
        pub fn local_init_expr(local: &Local) -> Option<&syn::Expr> {
            local.init.as_ref().map(|li| &*li.expr)
        }

        /// If the expression is a call (`Expr::Call`), returns the
        /// normalized path of the callee. None if it is not a call.
        pub fn call_path(expr: &syn::Expr) -> Option<String> {
            // We traverse parentheses so that `(Arc::new(...))` matches.
            let mut e = expr;
            while let syn::Expr::Paren(p) = e {
                e = &*p.expr;
            }
            match e {
                syn::Expr::Call(c) => Some(ts(&*c.func)),
                _ => None,
            }
        }

        /// Returns the method names in the chain of method
        /// calls that ends in `expr`, in application order
        /// (receiver → tips). E.g. `xs.lock().unwrap().clone().into_iter()`
        /// → `["borrow", "clone", "into_iter"]`.
        ///
        /// Traverses parentheses and casts (`expr as T`) — if `expr`
        /// is `(xs.lock().unwrap().len() as i64)` returns the chain
        /// inside the cast, ignoring the cast.
        pub fn method_chain_names(expr: &syn::Expr) -> Vec<String> {
            let mut names = Vec::new();
            let mut e = expr;
            loop {
                match e {
                    syn::Expr::MethodCall(mc) => {
                        names.push(mc.method.to_string());
                        e = &*mc.receiver;
                    }
                    syn::Expr::Paren(p) => {
                        e = &*p.expr;
                    }
                    syn::Expr::Cast(c) => {
                        e = &*c.expr;
                    }
                    _ => break,
                }
            }
            names.reverse();
            names
        }

        /// Finds the first macro call with the given name inside
        /// expr and returns its normalized tokens. None if there is
        /// no match.
        pub fn find_macro_args(expr: &syn::Expr, macro_name: &str) -> Option<String> {
            use syn::visit::Visit;
            struct V<'a> {
                name: &'a str,
                found: Option<String>,
            }
            impl<'a, 'ast> Visit<'ast> for V<'a> {
                fn visit_macro(&mut self, m: &'ast syn::Macro) {
                    if self.found.is_none()
                        && m.path.segments.last().is_some_and(|s| s.ident == self.name)
                    {
                        self.found = Some(ts(&m.tokens));
                    }
                    syn::visit::visit_macro(self, m);
                }
            }
            let mut v = V {
                name: macro_name,
                found: None,
            };
            v.visit_expr(expr);
            v.found
        }

        /// Counts how many times a call to a method with the
        /// given name appears at any level of the expression's AST.
        pub fn count_method_calls_in_expr(expr: &syn::Expr, method_name: &str) -> usize {
            use syn::visit::Visit;
            struct V<'a> {
                name: &'a str,
                count: usize,
            }
            impl<'a, 'ast> Visit<'ast> for V<'a> {
                fn visit_expr_method_call(&mut self, e: &'ast syn::ExprMethodCall) {
                    if e.method == self.name {
                        self.count += 1;
                    }
                    syn::visit::visit_expr_method_call(self, e);
                }
            }
            let mut v = V {
                name: method_name,
                count: 0,
            };
            v.visit_expr(expr);
            v.count
        }

        /// True if at any level of expr a call to a method with the
        /// given name appears.
        pub fn contains_method_call_in_expr(expr: &syn::Expr, method_name: &str) -> bool {
            count_method_calls_in_expr(expr, method_name) > 0
        }

        /// True if expr contains a macro invocation with the
        /// given name (recursive search).
        pub fn contains_macro_in_expr(expr: &syn::Expr, macro_name: &str) -> bool {
            find_macro_args(expr, macro_name).is_some()
        }

        /// If expr is a cast `<inner> as <ty>` (optionally wrapped in
        /// parentheses), returns the normalized destination type of
        /// the cast. None if the root expression is not a cast.
        pub fn cast_target_type(expr: &syn::Expr) -> Option<String> {
            let mut e = expr;
            while let syn::Expr::Paren(p) = e {
                e = &*p.expr;
            }
            match e {
                syn::Expr::Cast(c) => Some(ts(&*c.ty)),
                _ => None,
            }
        }

        /// Returns the attributes of a `fn` as tokenized strings.
        /// Useful for verifying `#[tokio::main(...)]` and similar.
        pub fn fn_attrs(f: &ItemFn) -> Vec<String> {
            f.attrs.iter().map(ts).collect()
        }

        /// True if the `fn` is marked as `async`.
        pub fn fn_is_async(f: &ItemFn) -> bool {
            f.sig.asyncness.is_some()
        }

        /// Returns the body of a `fn` tokenized and normalized.
        pub fn fn_body_text(f: &ItemFn) -> String {
            ts(&f.block)
        }

        /// Returns the `(pat, ty)` pairs of the `fn` params as
        /// tokenized strings. Useful for verifying that a handler has
        /// specific axum extractors as params.
        pub fn fn_param_pats_and_types(f: &ItemFn) -> Vec<(String, String)> {
            f.sig
                .inputs
                .iter()
                .filter_map(|arg| match arg {
                    syn::FnArg::Typed(pt) => Some((ts(&*pt.pat), ts(&*pt.ty))),
                    _ => None,
                })
                .collect()
        }

        /// Finds a top-level macro invocation by name of the
        /// final segment of the path (e.g. `thread_local`). None if not.
        pub fn find_top_macro<'a>(file: &'a File, name: &str) -> Option<&'a syn::ItemMacro> {
            file.items.iter().find_map(|i| match i {
                Item::Macro(im) if im.mac.path.segments.last().is_some_and(|s| s.ident == name) => {
                    Some(im)
                }
                _ => None,
            })
        }

        /// Counts how many top-level invocations of a macro with the
        /// given name there are in the file.
        pub fn count_top_macros(file: &File, name: &str) -> usize {
            file.items
                .iter()
                .filter(|i| {
                    matches!(
                        i,
                        Item::Macro(im) if im.mac.path.segments.last().is_some_and(|s| s.ident == name)
                    )
                })
                .count()
        }

        /// Returns all `.route(...)` invocations inside `fn main` as
        /// `(first_arg_tokenized, second_arg_tokenized)`.
        /// For `.route("/users", axum::routing::get(__handler_x))` gives
        /// `("\"/users\"", "axum :: routing :: get ( __handler_x )")`.
        pub fn find_route_registrations(file: &File) -> Vec<(String, String)> {
            let main = match find_item_fn(file, "main") {
                Some(m) => m,
                None => return Vec::new(),
            };
            use syn::visit::Visit;
            struct V {
                out: Vec<(String, String)>,
            }
            impl<'ast> Visit<'ast> for V {
                fn visit_expr_method_call(&mut self, e: &'ast syn::ExprMethodCall) {
                    if e.method == "route" && e.args.len() == 2 {
                        let mut iter = e.args.iter();
                        let p = iter.next().unwrap();
                        let h = iter.next().unwrap();
                        self.out.push((ts(p), ts(h)));
                    }
                    syn::visit::visit_expr_method_call(self, e);
                }
            }
            let mut v = V { out: Vec::new() };
            v.visit_block(&main.block);
            v.out
        }

        /// Looks for a `let` with a given name inside a `fn`,
        /// recursively. Returns a clone of the `Local` or None.
        pub fn find_local_in_fn(f: &ItemFn, name: &str) -> Option<Local> {
            use syn::visit::Visit;
            struct V<'a> {
                name: &'a str,
                found: Option<Local>,
            }
            impl<'a, 'ast> Visit<'ast> for V<'a> {
                fn visit_local(&mut self, l: &'ast Local) {
                    if self.found.is_none() && pat_binds(&l.pat, self.name) {
                        self.found = Some(l.clone());
                    }
                    syn::visit::visit_local(self, l);
                }
            }
            let mut v = V { name, found: None };
            v.visit_block(&f.block);
            v.found
        }

        /// Looks for all `let`s with a given name inside a `fn`
        /// (any nesting level). Useful for validating
        /// reassignment vs multiple binding creation.
        pub fn count_locals_in_fn(f: &ItemFn, name: &str) -> usize {
            use syn::visit::Visit;
            struct V<'a> {
                name: &'a str,
                count: usize,
            }
            impl<'a, 'ast> Visit<'ast> for V<'a> {
                fn visit_local(&mut self, l: &'ast Local) {
                    if pat_binds(&l.pat, self.name) {
                        self.count += 1;
                    }
                    syn::visit::visit_local(self, l);
                }
            }
            let mut v = V { name, count: 0 };
            v.visit_block(&f.block);
            v.count
        }

        /// True if the `fn` body contains a return whose expression
        /// matches (tokenized) with all given needles.
        pub fn fn_body_returns_any_matching(f: &ItemFn, needles: &[&str]) -> bool {
            use syn::visit::Visit;
            struct V<'a, 'b> {
                needles: &'a [&'b str],
                found: bool,
            }
            impl<'a, 'b, 'ast> Visit<'ast> for V<'a, 'b> {
                fn visit_expr_return(&mut self, e: &'ast syn::ExprReturn) {
                    if let Some(ex) = &e.expr {
                        let t = ts(&**ex);
                        if self.needles.iter().all(|n| t.contains(n)) {
                            self.found = true;
                        }
                    }
                    syn::visit::visit_expr_return(self, e);
                }
            }
            let mut v = V {
                needles,
                found: false,
            };
            v.visit_block(&f.block);
            v.found
        }

        /// Finds the first `match` expr in the stmts (recursive search).
        /// Returns a clone of `ExprMatch` or None.
        pub fn find_match(stmts: &[Stmt]) -> Option<syn::ExprMatch> {
            use syn::visit::Visit;
            struct V {
                found: Option<syn::ExprMatch>,
            }
            impl<'ast> Visit<'ast> for V {
                fn visit_expr_match(&mut self, e: &'ast syn::ExprMatch) {
                    if self.found.is_none() {
                        self.found = Some(e.clone());
                    }
                    syn::visit::visit_expr_match(self, e);
                }
            }
            let mut v = V { found: None };
            for s in stmts {
                v.visit_stmt(s);
            }
            v.found
        }

        /// Returns the normalized tokens of the first macro call with the
        /// given name in the stmts (recursive search, traverses all
        /// nestings). None if there is no match.
        pub fn first_macro_args_in_stmts(stmts: &[Stmt], name: &str) -> Option<String> {
            use syn::visit::Visit;
            struct V<'a> {
                name: &'a str,
                found: Option<String>,
            }
            impl<'a, 'ast> Visit<'ast> for V<'a> {
                fn visit_macro(&mut self, m: &'ast syn::Macro) {
                    if self.found.is_none()
                        && m.path.segments.last().is_some_and(|s| s.ident == self.name)
                    {
                        self.found = Some(ts(&m.tokens));
                    }
                    syn::visit::visit_macro(self, m);
                }
            }
            let mut v = V { name, found: None };
            for s in stmts {
                v.visit_stmt(s);
            }
            v.found
        }

        /// True if a `match` appears in the `fn` body with at least one
        /// arm whose pat contains the given needle (tokenized).
        pub fn fn_body_has_match_arm_pat(f: &ItemFn, pat_needle: &str) -> bool {
            use syn::visit::Visit;
            struct V<'a> {
                needle: &'a str,
                found: bool,
            }
            impl<'a, 'ast> Visit<'ast> for V<'a> {
                fn visit_arm(&mut self, a: &'ast syn::Arm) {
                    if ts(&a.pat).contains(self.needle) {
                        self.found = true;
                    }
                    syn::visit::visit_arm(self, a);
                }
            }
            let mut v = V {
                needle: pat_needle,
                found: false,
            };
            v.visit_block(&f.block);
            v.found
        }
    }

    #[test]
    fn empty_program_generates_empty_main() {
        let code = gen("").unwrap();
        let file = ast_test::parse(&code);
        let main = ast_test::find_item_fn(&file, "main").expect("missing fn main");
        // empty main: no params, no return type, body without stmts.
        assert_eq!(ast_test::fn_arity(main), 0);
        assert!(ast_test::fn_return_type(main).is_none());
        assert!(
            main.block.stmts.is_empty(),
            "expected empty main body, got: {}",
            ast_test::fn_body_text(main)
        );
    }

    #[test]
    fn let_int_annotated_generates_i64() {
        let file = ast_test::parse(&gen("let x: Int = 42").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "x").expect("missing let x");
        assert!(ast_test::local_is_mut(l));
        assert_eq!(ast_test::local_type(l).as_deref(), Some("i64"));
        assert_eq!(ast_test::local_init(l).as_deref(), Some("42i64"));
    }

    #[test]
    fn let_int_inferred_generates_i64() {
        let file = ast_test::parse(&gen("let x = 42").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "x").expect("missing let x");
        assert_eq!(ast_test::local_type(l).as_deref(), Some("i64"));
        assert_eq!(ast_test::local_init(l).as_deref(), Some("42i64"));
    }

    #[test]
    fn let_float_annotated_generates_f64_with_int_coercion() {
        let file = ast_test::parse(&gen("let pi: Float = 3").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "pi").expect("missing let pi");
        assert_eq!(ast_test::local_type(l).as_deref(), Some("f64"));
        // El init coerciona Int→Float: `(3i64 as f64)`.
        let init = ast_test::local_init(l).unwrap();
        assert!(
            init.contains("3i64") && init.contains("as f64"),
            "expected init with Int→Float coercion, was: {}",
            init
        );
    }

    #[test]
    fn let_str_generates_string() {
        let file = ast_test::parse(&gen("let name = \"Fitz\"").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "name").expect("missing let name");
        assert_eq!(ast_test::local_type(l).as_deref(), Some("String"));
        let init = ast_test::local_init(l).unwrap();
        assert!(
            init.contains("String :: from") && init.contains("\"Fitz\""),
            "expected init `String::from(\"Fitz\")`, was: {}",
            init
        );
    }

    #[test]
    fn binop_int_int_is_int() {
        let file = ast_test::parse(&gen("let x = 1 + 2").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "x").expect("missing let x");
        assert_eq!(ast_test::local_type(l).as_deref(), Some("i64"));
        let init = ast_test::local_init(l).unwrap();
        assert!(
            init.contains("1i64") && init.contains("2i64") && init.contains("+"),
            "expected init `1i64 + 2i64`, was: {}",
            init
        );
    }

    #[test]
    fn binop_int_float_coerces_to_float() {
        let file = ast_test::parse(&gen("let x = 1 + 2.0").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "x").expect("missing let x");
        // El resultado tipa como f64 (Int+Float promueve a Float).
        assert_eq!(ast_test::local_type(l).as_deref(), Some("f64"));
        let init = ast_test::local_init(l).unwrap();
        assert!(
            init.contains("1i64") && init.contains("as f64") && init.contains("2f64"),
            "expected Int→Float coercion in the init, was: {}",
            init
        );
    }

    // B9 (sub-paso 5 cosecha post-fitzwatch, 2026-06-19) —
    // Nullable<T> vs concrete T equality/inequality emits
    // `<opt>.as_ref() == Some(&<conc>)` instead of failing the
    // type check or emitting incompatible Rust.
    #[test]
    fn binop_eq_nullable_str_vs_str_emits_as_ref_some_b9() {
        let src = "let s: Str? = null\nlet b = (s == \"hello\")";
        let code = gen(src).expect("codegen OK");
        assert!(
            code.contains(").as_ref() == Some(&"),
            "expected `.as_ref() == Some(&...)` in generated code, was: {}",
            code
        );
    }

    #[test]
    fn binop_neq_nullable_str_vs_str_emits_as_ref_some_b9() {
        let src = "let s: Str? = null\nlet b = (s != \"down\")";
        let code = gen(src).expect("codegen OK");
        assert!(
            code.contains(").as_ref() != Some(&"),
            "expected `.as_ref() != Some(&...)` in generated code, was: {}",
            code
        );
    }

    #[test]
    fn binop_eq_nullable_int_vs_int_emits_as_ref_some_b9() {
        let src = "let n: Int? = null\nlet b = (n == 7)";
        let code = gen(src).expect("codegen OK");
        assert!(
            code.contains(").as_ref() == Some(&"),
            "expected `.as_ref() == Some(&...)` in generated code, was: {}",
            code
        );
    }

    #[test]
    fn binop_eq_str_vs_nullable_str_emits_as_ref_some_swapped_b9() {
        // Same pattern from the LHS side: `"hello" == s` should also
        // work (we swap arguments and emit the same shape).
        let src = "let s: Str? = null\nlet b = (\"hello\" == s)";
        let code = gen(src).expect("codegen OK");
        assert!(
            code.contains(").as_ref() == Some(&"),
            "expected `.as_ref() == Some(&...)` even when Nullable is on the right, was: {}",
            code
        );
    }

    #[test]
    fn str_interp_generates_format_macro() {
        // For an Int var inside StrInterp, we generate `format!`
        // passing the var directly (no `.clone()` needed).
        let code = gen("let n = 5\nlet s = \"x es {n}\"").unwrap();
        let file = ast_test::parse(&code);
        let stmts = ast_test::main_block_stmts(&file);
        let args = ast_test::first_macro_args_in_stmts(stmts, "format").expect("missing format!");
        assert!(
            args.contains("\"x es {}\""),
            "expected template `\"x es {{}}\"`, got: {}",
            args
        );
        // n: Int (Copy) passes directly without .clone().
        assert!(
            !args.contains("n . clone") && !args.contains("n .clone"),
            "Int should not use .clone(), got: {}",
            args
        );
    }

    #[test]
    fn str_interp_with_var_str_clones() {
        // For Str, we generate `.clone()` because format! borrows
        // but we keep passing the evaluated `Ident`, which does include
        // the clone.
        let code = gen("let name = \"Fitz\"\nlet s = \"hola, {name}\"").unwrap();
        let file = ast_test::parse(&code);
        let stmts = ast_test::main_block_stmts(&file);
        let args = ast_test::first_macro_args_in_stmts(stmts, "format").expect("missing format!");
        assert!(
            args.contains("\"hola, {}\"") && args.contains("name . clone"),
            "expected `format!(\"hola, {{}}\", name.clone())`, got: {}",
            args
        );
    }

    #[test]
    fn print_generates_println_macro() {
        let file = ast_test::parse(&gen("let x: Int = 1\nprint(x)").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        assert_eq!(
            ast_test::count_macro_calls(stmts, "println"),
            1,
            "expected exactly 1 println!"
        );
    }

    #[test]
    fn print_multiple_args_generates_format_string_with_spaces() {
        // The contract is: print(a, b) emits ONE single println! that
        // contains both `a` and `b` (space separation in the
        // format string is the canonical format, but here we just need
        // structure: 1 println, args contain both vars).
        let file = ast_test::parse(&gen("let a: Int = 1\nlet b: Int = 2\nprint(a, b)").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        assert_eq!(ast_test::count_macro_calls(stmts, "println"), 1);
        // We inspect the last stmt (should be the println!).
        let last = ast_test::ts(stmts.last().unwrap());
        assert!(
            last.contains("println !") && last.contains(", a") && last.contains(", b"),
            "expected println! with args a and b, was: {}",
            last
        );
    }

    #[test]
    fn print_without_args_generates_empty_println() {
        // `print()` without args → `println!()` with no internal tokens.
        let file = ast_test::parse(&gen("print()").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        assert_eq!(ast_test::count_macro_calls(stmts, "println"), 1);
        let last = ast_test::ts(stmts.last().unwrap());
        // There must be no `,` inside the println!() — no args.
        assert!(
            last.contains("println ! ()") || last.contains("println !()"),
            "expected empty println!(), was: {}",
            last
        );
    }

    #[test]
    fn fn_top_level_emits_full_signature() {
        let file = ast_test::parse(&gen("fn double(n: Int) -> Int { return n * 2 }").unwrap());
        let f = ast_test::find_item_fn(&file, "double").expect("missing fn double");
        assert_eq!(ast_test::fn_arity(f), 1);
        assert_eq!(ast_test::fn_param_types(f), vec!["i64".to_string()]);
        assert_eq!(ast_test::fn_return_type(f).as_deref(), Some("i64"));
    }

    #[test]
    fn fn_arrow_emits_implicit_return() {
        // Both the body with `{ return n * 2 }` and the arrow
        // `=> n * 2` must emit the same signature and a `return` in
        // the body. The difference vs the previous test is only syntactic
        // on the Fitz side.
        let file = ast_test::parse(&gen("fn double(n: Int) -> Int => n * 2").unwrap());
        let f = ast_test::find_item_fn(&file, "double").expect("missing fn double");
        assert_eq!(ast_test::fn_arity(f), 1);
        assert_eq!(ast_test::fn_return_type(f).as_deref(), Some("i64"));
        // The body must contain a `return` (it's not just a tail
        // expression — codegen always emits `return ...`).
        let body = ast_test::ts(&f.block);
        assert!(
            body.contains("return"),
            "expected `return` in the arrow fn body, was: {}",
            body
        );
    }

    #[test]
    fn call_to_top_level_fn_resolves_return_type() {
        let file = ast_test::parse(
            &gen("fn double(n: Int) -> Int => n * 2\n\
                 let x = double(5)")
            .unwrap(),
        );
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "x").expect("missing let x");
        // x must end up typed as i64 (the return type of double).
        assert_eq!(ast_test::local_type(l).as_deref(), Some("i64"));
        let init = ast_test::local_init(l).unwrap();
        assert!(
            init.contains("double") && init.contains("5i64"),
            "expected init `double(5i64)`, was: {}",
            init
        );
    }

    #[test]
    fn if_else_generates_rust_structure() {
        let file = ast_test::parse(
            &gen("let x = 1\nif (x > 0) { print(\"pos\") } else { print(\"neg\") }").unwrap(),
        );
        let stmts = ast_test::main_block_stmts(&file);
        let if_expr = ast_test::find_if(stmts).expect("missing if/else in main");
        // Both branches present (else_branch != None).
        assert!(if_expr.else_branch.is_some(), "expected else branch");
        // The if test compares `x > 0`.
        let cond = ast_test::ts(&*if_expr.cond);
        assert!(cond.contains("x") && cond.contains(">"), "cond: {}", cond);
    }

    #[test]
    fn while_generates_rust_structure() {
        let file = ast_test::parse(&gen("let n = 0\nwhile (n < 3) { n = n + 1 }").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        let w = ast_test::find_while_loop(stmts).expect("missing while loop");
        let cond = ast_test::ts(&*w.cond);
        assert!(
            cond.contains("n") && cond.contains("<") && cond.contains("3i64"),
            "while cond: {}",
            cond
        );
        // The body must reassign `n` (= not a `let`).
        let body = ast_test::ts(&w.body);
        assert!(body.contains("n ="), "while body: {}", body);
    }

    #[test]
    fn for_in_range_generates_rust() {
        let file = ast_test::parse(&gen("for i in 0..3 { print(i) }").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        let f = ast_test::find_for_loop(stmts).expect("missing for loop");
        // pat is `mut i`.
        assert!(
            ast_test::ts(&f.pat).contains("i"),
            "for pat: {}",
            ast_test::ts(&f.pat)
        );
        // expr is a range `0..3` (both bounds present).
        let expr = ast_test::ts(&*f.expr);
        assert!(
            expr.contains("0i64") && expr.contains("3i64") && expr.contains(".."),
            "for expr: {}",
            expr
        );
    }

