    #[test]
    fn field_access_int_emits_block_without_field_clone() {
        // F17.4b: field access is emitted as a block with a scoped
        // guard to avoid holding the Mutex cross-expression.
        // For Int (Copy) the block return is `__g.id` (not
        // `__g.id.clone()`). `u.clone()` does appear (Arc::clone to
        // share the handle); what must NOT appear is
        // `__g.id.clone()` (cloning a Copy value is redundant).
        let code = gen("type U { id: Int }\nlet u = U { id: 1 }\nlet n = u.id").unwrap();
        let file = ast_test::parse(&code);
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "n").expect("missing let n");
        let init = ast_test::local_init(l).unwrap();
        assert!(
            init.contains("let __g") && init.contains("__g . id"),
            "expected block `{{ let __g = ...; __g.id }}`, was: {}",
            init
        );
        assert!(
            !init.contains("__g . id . clone"),
            "Int (Copy) should not be cloned, was: {}",
            init
        );
    }

