    // (Unknown methods on Str are caught by the checker before reaching
    // codegen, so we don't test that path from here.)

    #[test]
    fn type_def_emits_derive_clone_and_impl_partialeq() {
        let code = gen("type U { id: Int }").unwrap();
        let file = ast_test::parse(&code);
        let s = ast_test::find_item_struct(&file, "UData").expect("missing UData");
        assert!(
            ast_test::struct_has_derive(s, "Clone"),
            "expected derive(Clone)"
        );
        // F17.4b: PartialEq is no longer derived because `std::sync::Mutex<T>`
        // does not impl PartialEq. It is emitted manually below, mirroring the
        // interpreter's pattern (`Arc::ptr_eq` shortcut + lock+deref per
        // nominal field).
        assert!(
            !ast_test::struct_has_derive(s, "PartialEq"),
            "PartialEq must NOT be derived post-F17.4b (Mutex does not impl PartialEq)"
        );
        assert!(
            ast_test::find_impl(&file, "PartialEq", "UData").is_some(),
            "expected impl PartialEq for UData (manual post-F17.4b)"
        );
    }

    // ---- 5b.3: lists, maps, indexing, built-in methods ----

    #[test]
    fn list_literal_emits_arc_mutex_vec() {
        // `[1, 2, 3]` is modeled as `Arc<Mutex<Vec<i64>>>`. The items
        // are coerced to the common type (here Int → i64) and built with
        // the vec![] macro.
        let file = ast_test::parse(&gen("let xs: List<Int> = [1, 2, 3]").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "xs").expect("missing let xs");
        assert_eq!(
            ast_test::local_type(l).as_deref(),
            Some("Arc < Mutex < Vec < i64 > > >"),
            "declared type of xs"
        );
        let init = ast_test::local_init_expr(l).expect("missing init of xs");
        // The init is `Arc::new(Mutex::new(vec![...]))`. We confirm the
        // outer call to the Rc::new path and the presence of the vec! macro
        // with the 3 items having i64 suffix.
        assert_eq!(ast_test::call_path(init).as_deref(), Some("Arc :: new"));
        let vec_args =
            ast_test::find_macro_args(init, "vec").expect("expected a vec! macro inside the init");
        for n in ["1i64", "2i64", "3i64"] {
            assert!(
                vec_args.contains(n),
                "expected item {} in vec!, was: {}",
                n,
                vec_args
            );
        }
    }

