    #[test]
    fn list_indexing_emits_borrow_clone() {
        // I.1 (mini-batch I): indexing now emits a block
        // with bounds check + negative wrap + clone. We verify
        // that the key pieces are present.
        let file = ast_test::parse(&gen("let xs: List<Int> = [10, 20]\nlet x = xs[0]").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "x").expect("missing let x");
        // The `x` binding must end up typed i64 (List<Int> indexing).
        assert_eq!(ast_test::local_type(l).as_deref(), Some("i64"));
        let init = ast_test::local_init_expr(l).unwrap();
        let ts = ast_test::ts(init);
        // The new emit uses `lock().unwrap()` inside the block.
        assert!(ts.contains("lock"), "expected .lock(), was: {}", ts);
        // And the final `clone()` of the element.
        assert!(ts.contains("clone"), "expected .clone(), was: {}", ts);
        // Verify the negative wrap (signature of the new emit).
        assert!(
            ts.contains("__len + __i"),
            "expected negative wrap `__len + __i`, was: {}",
            ts
        );
    }

    #[test]
    fn map_indexing_emits_linear_search_with_panic() {
        // `m["a"]` → block that does linear search and panics if missing.
        let file =
            ast_test::parse(&gen("let m: Map<Str, Int> = {\"a\": 1}\nlet n = m[\"a\"]").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "n").expect("missing let n");
        let init = ast_test::local_init_expr(l).unwrap();
        // The pipeline `.iter().find(...).unwrap_or_else(|| panic!(...))`
        // is inside the init: I check for the presence of key methods.
        assert!(
            ast_test::contains_method_call_in_expr(init, "find"),
            "expected `.find(...)` in the init of n, was: {}",
            ast_test::ts(init)
        );
        // The panic with the interpreter message stays as a string
        // (it's a bit-a-bit contract with the evaluator).
        let panic_args =
            ast_test::find_macro_args(init, "panic").expect("expected a panic! inside the block");
        assert!(
            panic_args.contains("key not found in map"),
            "expected interpreter message in panic!, was: {}",
            panic_args
        );
    }

    #[test]
    fn for_over_list_generates_snapshot_iter() {
        // `for v in xs` → snapshot via `let __for_snap = xs.lock().unwrap().clone();`
        // ANTES del for + `for v in __for_snap.into_iter()`. Post-B17 fix
        // (cosecha post-fitzwatch): bindear el clone a una variable local
        // libera el MutexGuard temporal antes de que el body corra, evitando
        // que el guard sobreviva cross-await (rompía Send en handlers async
        // que iteraban listas).
        let code = gen("let xs: List<Int> = [1, 2, 3]\nfor v in xs { print(v) }").unwrap();
        // The textual output must contain the snapshot pattern AND the
        // body must iterate over the snapshot (not the original lock chain).
        assert!(
            code.contains("let __for_snap = ") && code.contains(".lock().unwrap().clone();"),
            "expected `let __for_snap = ... .lock().unwrap().clone();` snapshot binding before the for, code was:\n{}",
            code
        );
        assert!(
            code.contains("for mut v in __for_snap.into_iter()"),
            "expected `for v in __for_snap.into_iter()` body iteration, code was:\n{}",
            code
        );
    }

