    #[test]
    fn list_pop_emits_lock_pop_with_expect() {
        let file = ast_test::parse(&gen("let xs: List<Int> = [1]\nlet x = xs.pop()").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "x").expect("missing let x");
        let init = ast_test::local_init(l).unwrap();
        // The pop translates to `.lock().unwrap().pop().expect("...")` —
        // `.expect(...)` panics with the same interpreter message.
        assert!(
            init.contains("lock") && init.contains("pop") && init.contains("expect"),
            "expected pipeline lock + pop + expect, was: {}",
            init
        );
        // The expect message must mention `pop` and `empty list`
        // (matches the interpreter's).
        assert!(
            init.contains("pop") && init.contains("empty list"),
            "expected expect message about empty list, was: {}",
            init
        );
    }

