    #[test]
    fn list_map_with_inline_fnexpr_emits_closure() {
        let file = ast_test::parse(
            &gen("let xs: List<Int> = [1, 2, 3]\nlet ys = xs.map(fn(x) => x * 2)").unwrap(),
        );
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "ys").expect("missing let ys");
        assert!(ast_test::local_is_mut(l));
        assert_eq!(
            ast_test::local_type(l).as_deref(),
            Some("Arc < Mutex < Vec < i64 > > >"),
            "expected `ys` to be typed as List<Int>"
        );
        // The init invokes `.map(|x: i64| -> i64 { ... })` inside an
        // Arc::new(Mutex::new(...)). Structural check: there is a
        // method call `map` and the first arg of map is a typed
        // closure `|x: i64| -> i64`.
        let init = ast_test::local_init_expr(l).unwrap();
        assert!(
            ast_test::contains_method_call_in_expr(init, "map"),
            "expected `.map(...)` in the init, was: {}",
            ast_test::ts(init)
        );
        let init_text = ast_test::ts(init);
        assert!(
            init_text.contains("| x : i64 | -> i64"),
            "expected closure `|x: i64| -> i64`, was: {}",
            init_text
        );
        assert!(
            init_text.contains("Arc :: new (Mutex :: new"),
            "expected wrapping Arc::new(Mutex::new(...)), was: {}",
            init_text
        );
    }

    #[test]
    fn list_filter_with_inline_fnexpr_emits_manual_for() {
        // Filter uses a manual for (not .filter()) because the callback
        // takes T by value but `Iterator::filter` wants &T.
        let file = ast_test::parse(
            &gen("let xs: List<Int> = [1, 2, 3]\nlet ys = xs.filter(fn(x) => x > 1)").unwrap(),
        );
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "ys").expect("missing let ys");
        let init = ast_test::local_init_expr(l).unwrap();
        let init_text = ast_test::ts(init);
        // The init block must declare a closure `__cb` typed
        // `|x: i64| -> bool`.
        assert!(
            init_text.contains("let __cb = | x : i64 | -> bool"),
            "expected callback binding `__cb`, was: {}",
            init_text
        );
        // The callback is applied inside a for with clone of the item.
        assert!(
            init_text.contains("__cb (__it . clone ())"),
            "expected application `__cb(__it.clone())` inside the for, was: {}",
            init_text
        );
    }

    #[test]
    fn map_method_chaining_works() {
        // `xs.map(f).map(g)` must compose. The test is structural:
        // the output type of the first map feeds the
        // next without friction.
        let file = ast_test::parse(
            &gen("let xs: List<Int> = [1, 2]\n\
                 let ys = xs.map(fn(x) => x * 2).map(fn(x) => x + 1)")
            .unwrap(),
        );
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "ys").expect("missing let ys");
        let init = ast_test::local_init_expr(l).unwrap();
        // We expect two `|x: i64| -> i64` closures (one per .map)
        // inside the init of ys.
        let init_text = ast_test::ts(init);
        let n = init_text.matches("| x : i64 | -> i64").count();
        assert!(
            n >= 2,
            "expected ≥2 closures `|x: i64| -> i64` in chain, was {} in: {}",
            n,
            init_text
        );
    }

    #[test]
    fn map_has_emits_iter_any() {
        // `m.has(k)` translates to a block
        // `{ let __k = k; (m.clone()).lock().unwrap().iter().any(...) }`. The
        // structural check looks for `iter` + `any` inside the init,
        // regardless of whether they're wrapped in block or expression.
        let file = ast_test::parse(
            &gen("let m: Map<Str, Int> = {\"a\": 1}\nlet b = m.has(\"a\")").unwrap(),
        );
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "b").expect("missing let b");
        let init = ast_test::local_init_expr(l).unwrap();
        assert!(
            ast_test::contains_method_call_in_expr(init, "iter"),
            "expected `.iter()` in the init of b, was: {}",
            ast_test::ts(init)
        );
        assert!(
            ast_test::contains_method_call_in_expr(init, "any"),
            "expected `.any(...)` in the init of b, was: {}",
            ast_test::ts(init)
        );
        // The `b` binding's type is bool.
        assert_eq!(ast_test::local_type(l).as_deref(), Some("bool"));
    }

    #[test]
    fn map_keys_emits_new_list_of_keys() {
        let file = ast_test::parse(
            &gen("let m: Map<Str, Int> = {\"a\": 1, \"b\": 2}\nlet ks = m.keys()").unwrap(),
        );
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "ks").expect("missing let ks");
        // keys() returns `List<Str>` wrapped in Rc/RefCell.
        assert_eq!(
            ast_test::local_type(l).as_deref(),
            Some("Arc < Mutex < Vec < String > > >"),
            "expected keys to return List<Str>"
        );
        let init = ast_test::local_init_expr(l).unwrap();
        // The inner pipeline uses `.iter().map(...).collect()`.
        let init_text = ast_test::ts(init);
        assert!(
            init_text.contains(". iter () . map (| (__k , _) | __k . clone ())"),
            "expected pipeline `.iter().map(|(__k, _)| __k.clone())`, was: {}",
            init_text
        );
        assert!(
            init_text.contains("collect :: < Vec < _ > > ()"),
            "expected `.collect::<Vec<_>>()`, was: {}",
            init_text
        );
    }

    #[test]
    fn map_values_emits_new_list_of_values() {
        let file = ast_test::parse(
            &gen("let m: Map<Str, Int> = {\"a\": 1}\nlet vs = m.values()").unwrap(),
        );
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "vs").expect("missing let vs");
        assert_eq!(
            ast_test::local_type(l).as_deref(),
            Some("Arc < Mutex < Vec < i64 > > >"),
            "expected values to return List<Int>"
        );
        let init = ast_test::local_init_expr(l).unwrap();
        let init_text = ast_test::ts(init);
        assert!(
            init_text.contains(". iter () . map (| (_ , __v) | __v . clone ())"),
            "expected pipeline `.iter().map(|(_, __v)| __v.clone())`, was: {}",
            init_text
        );
        assert!(
            init_text.contains("collect :: < Vec < _ > > ()"),
            "expected `.collect::<Vec<_>>()`, was: {}",
            init_text
        );
    }

    #[test]
    fn map_len_method_emits_borrow_len_as_i64() {
        let file =
            ast_test::parse(&gen("let m: Map<Str, Int> = {\"a\": 1}\nlet n = m.len()").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "n").expect("missing let n");
        assert_eq!(ast_test::local_type(l).as_deref(), Some("i64"));
        let init = ast_test::local_init_expr(l).unwrap();
        assert_eq!(
            ast_test::cast_target_type(init).as_deref(),
            Some("i64"),
            "expected cast final `as i64`"
        );
        let chain = ast_test::method_chain_names(init);
        assert!(
            chain.contains(&"lock".to_string()) && chain.contains(&"len".to_string()),
            "expected chain with lock + len, was: {:?}",
            chain
        );
    }

    #[test]
    fn list_find_emits_result_with_loop() {
        // 5b.4: find returns `Result<T, String>` with Ok(item) at the first
        // match and `Err("not found")` if nothing matches. The binding
        // `x` must be typed `Result<i64, String>`.
        let file = ast_test::parse(
            &gen("let xs: List<Int> = [1, 2]\nlet x = xs.find(fn(n) => n > 0)").unwrap(),
        );
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "x").expect("missing let x");
        assert_eq!(
            ast_test::local_type(l).as_deref(),
            Some("Result < i64 , String >"),
            "expected `x: Result<i64, String>`"
        );
        // The init is a block with a manual loop; I check for the presence of
        // the key pieces (the Err message and the Ok assignment)
        // as substrings of the normalized representation — they are
        // stable codegen contracts.
        let init = ast_test::local_init_expr(l).unwrap();
        let init_text = ast_test::ts(init);
        assert!(
            init_text.contains("Err (String :: from (\"not found\"))"),
            "expected initializer with `Err(\"not found\")`, was: {}",
            init_text
        );
        assert!(
            init_text.contains("__result = Ok (__it) ; break ;"),
            "expected assignment `__result = Ok(__it); break;`, was: {}",
            init_text
        );
    }

    #[test]
    fn map_get_emits_result_with_linear_search() {
        // 5b.4: get returns `Result<V, String>`. The Err message matches
        // bit-a-bit the interpreter's: `key not found: <k>` with `<k>`
        // formatted inline (Str with quotes).
        let file = ast_test::parse(
            &gen("let m: Map<Str, Int> = {\"a\": 1}\nlet v = m.get(\"a\")").unwrap(),
        );
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "v").expect("missing let v");
        assert_eq!(
            ast_test::local_type(l).as_deref(),
            Some("Result < i64 , String >"),
            "expected `v: Result<i64, String>`"
        );
        let init = ast_test::local_init_expr(l).unwrap();
        // The Err message carries the template `key not found: {}`
        // (bit-a-bit contract with the interpreter) — I look for it inside
        // a format! macro call.
        let fmt = ast_test::find_macro_args(init, "format")
            .expect("expected a format! with the Err message");
        assert!(
            fmt.contains("key not found: {}"),
            "expected template `key not found: {{}}` in format!, was: {}",
            fmt
        );
        let init_text = ast_test::ts(init);
        assert!(
            init_text.contains("__result = Ok (__v . clone ()) ; break ;"),
            "expected assignment `__result = Ok(__v.clone()); break;`, was: {}",
            init_text
        );
    }

    #[test]
    fn standalone_fnexpr_emits_arc_dyn_fn() {
        // F12: FnExpr assigned to a var emits `Arc::new(move |...| ...) as
        // Arc<dyn Fn(...) -> ...>`. The var ends up typed as
        // `Arc<dyn Fn(i64) -> i64>` and can be invoked with `f(x)`.
        let file = ast_test::parse(
            &gen("let f: Fn(Int) -> Int = fn(x: Int) => x * 2\nprint(f(3))").unwrap(),
        );
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "f").expect("missing let f");
        assert_eq!(
            ast_test::local_type(l).as_deref(),
            Some("Arc < dyn Fn (i64) -> i64 + Send + Sync >"),
            "expected type `Arc<dyn Fn(i64) -> i64>`"
        );
        // The init must contain `Arc::new(move |x: i64| ...)`. I verify
        // substring over the normalized representation.
        let init_text = ast_test::ts(ast_test::local_init_expr(l).unwrap());
        assert!(
            init_text.contains("Arc :: new (move | x : i64 |"),
            "expected `Arc::new(move |x: i64| ...)`, was: {}",
            init_text
        );
    }

    #[test]
    fn fnexpr_without_param_annotation_gives_clear_error() {
        // F12: the compilable subset requires annotation on each param of
        // the FnExpr (debt 5b.1). Without annotation → explicit message.
        assert_err_contains(
            "let f: Fn(Int) -> Int = fn(x) => x * 2",
            &["anonymous", "type annotation"],
        );
    }

    #[test]
    fn named_fn_as_value_emits_arc_new() {
        // F12: `let g = square` where `square` is a top-level fn emits
        // `Arc::new(square) as Arc<dyn Fn(...) -> R>` with the signature from
        // fn_sigs.
        let file = ast_test::parse(
            &gen("fn square(n: Int) -> Int => n * n\nlet g: Fn(Int) -> Int = square\nprint(g(7))")
                .unwrap(),
        );
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "g").expect("missing let g");
        assert_eq!(
            ast_test::local_type(l).as_deref(),
            Some("Arc < dyn Fn (i64) -> i64 + Send + Sync >"),
            "expected type `Arc<dyn Fn(i64) -> i64>`"
        );
        let init_text = ast_test::ts(ast_test::local_init_expr(l).unwrap());
        assert!(
            init_text.contains("Arc :: new (square)"),
            "expected `Arc::new(square)`, was: {}",
            init_text
        );
    }

    #[test]
    fn fn_param_of_function_type_emits_arc_dyn_fn() {
        // F12: param `f: Fn(Int) -> Int` in the signature of the top-level fn
        // must translate to `Arc<dyn Fn(i64) -> i64>` in the header.
        let file = ast_test::parse(
            &gen("fn apply(f: Fn(Int) -> Int, x: Int) -> Int => f(x)\n\
                 fn square(n: Int) -> Int => n * n\n\
                 print(apply(square, 7))")
            .unwrap(),
        );
        // Header of `apply`: param types + return type.
        let apply = ast_test::find_item_fn(&file, "apply").expect("missing fn apply");
        assert_eq!(
            ast_test::fn_param_types(apply),
            vec!["Arc < dyn Fn (i64) -> i64 + Send + Sync >", "i64"],
            "param types of apply"
        );
        assert_eq!(
            ast_test::fn_return_type(apply).as_deref(),
            Some("i64"),
            "return type of apply"
        );
        // The call `apply(square, 7)` must wrap `square` in
        // `Arc::new(square)`. I look for it as a substring over the
        // tokenized `main` (the call lives inside the print).
        let main_text =
            ast_test::ts(ast_test::find_item_fn(&file, "main").expect("missing fn main"));
        assert!(
            main_text.contains("apply ((Arc :: new (square)"),
            "expected `apply((Arc::new(square) as ...))` in main, was: {}",
            main_text
        );
    }

    #[test]
    fn fn_as_return_type_emits_arc_dyn_fn() {
        // F12: `-> Fn(Int) -> Int` in a top-level fn emits the header
        // with return `Arc<dyn Fn(i64) -> i64>`. The inner closure that
        // captures `x` is translated with `move`.
        let file = ast_test::parse(
            &gen("fn make_adder(x: Int) -> Fn(Int) -> Int {\n\
                     return fn(y: Int) => x + y\n\
                 }\n\
                 let add5: Fn(Int) -> Int = make_adder(5)\n\
                 print(add5(3))")
            .unwrap(),
        );
        let make_adder =
            ast_test::find_item_fn(&file, "make_adder").expect("missing fn make_adder");
        assert_eq!(
            ast_test::fn_param_types(make_adder),
            vec!["i64"],
            "param types of make_adder"
        );
        assert_eq!(
            ast_test::fn_return_type(make_adder).as_deref(),
            Some("Arc < dyn Fn (i64) -> i64 + Send + Sync >"),
            "return type of make_adder"
        );
        // The body of make_adder contains `Arc::new(move |y: i64| ...)`.
        let body_text = ast_test::ts(&make_adder.block);
        assert!(
            body_text.contains("Arc :: new (move | y : i64 |"),
            "expected closure with `move` capturing x, was: {}",
            body_text
        );
    }

    #[test]
    fn closure_that_captures_non_copy_var_clones_outside() {
        // F12: closure that captures a non-Copy var (Str). The codegen
        // must emit `let saludo = saludo.clone();` outside to
        // preserve semantic aliasing without consuming the caller's
        // var.
        let file = ast_test::parse(
            &gen("let saludo = \"hola\"\n\
                 let f: Fn(Str) -> Str = fn(n: Str) => \"{saludo}, {n}!\"\n\
                 print(f(\"Fitz\"))")
            .unwrap(),
        );
        // The clone outside and the inner closure live inside the init
        // of `f` (it's a Rust block). I take the init and verify structural
        // substrings.
        let stmts = ast_test::main_block_stmts(&file);
        let l = ast_test::find_let(stmts, "f").expect("missing let f");
        let init_text = ast_test::ts(ast_test::local_init_expr(l).unwrap());
        assert!(
            init_text.contains("let saludo = saludo . clone () ;"),
            "expected clone of the capture before Rc::new, was: {}",
            init_text
        );
        assert!(
            init_text.contains("Arc :: new (move | n : String |"),
            "expected closure `Arc::new(move |n: String| ...)`, was: {}",
            init_text
        );
    }

    #[test]
    fn var_of_function_type_is_called_with_parens() {
        // F12: `f(x)` over a var Fn(Int) -> Int translates literally to
        // `f(x)` Rust — the auto-deref of `Rc<dyn Fn>` resolves it.
        let file = ast_test::parse(
            &gen("let f: Fn(Int) -> Int = fn(n: Int) => n + 1\nprint(f(10))").unwrap(),
        );
        // The body of main must contain a call `f(10i64)` inside
        // the println!. I look for it over the tokenized representation
        // (it's a macro call, the integer arg appears serialized).
        let main_text =
            ast_test::ts(ast_test::find_item_fn(&file, "main").expect("missing fn main"));
        assert!(
            main_text.contains("f (10i64)"),
            "expected `f(10i64)` in main, was: {}",
            main_text
        );
    }

    #[test]
    fn anonymous_inline_fn_as_arg_emits_direct_closure() {
        // F12: `apply(fn(n: Int) => n * 10, 7)` doesn't wrap in an
        // intermediate var — emits the `Arc::new(move |n: i64| ...)` inline
        // as argument.
        let file = ast_test::parse(
            &gen("fn apply(f: Fn(Int) -> Int, x: Int) -> Int => f(x)\n\
                 print(apply(fn(n: Int) => n * 10, 7))")
            .unwrap(),
        );
        let main_text =
            ast_test::ts(ast_test::find_item_fn(&file, "main").expect("missing fn main"));
        assert!(
            main_text.contains("apply ((Arc :: new (move | n : i64 |"),
            "expected the FnExpr emitted inline as arg of apply, was: {}",
            main_text
        );
    }

    #[test]
    fn print_of_list_emits_iter_inline() {
        // The print/interp builds the string `[a, b, c]` at runtime
        // by first binding the Rc to a var (temporary lifetime).
        let file = ast_test::parse(&gen("let xs: List<Int> = [1, 2]\nprint(xs)").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        // There must be a `println!` (it's the list print).
        assert!(
            ast_test::count_macro_calls(stmts, "println") >= 1,
            "expected at least one println! to print xs"
        );
        // The inline block binds the Rc to `__list` before the borrow
        // (temporary lifetime). I verify by checking the total code
        // contains a `let __list` inside some block.
        let code = ast_test::ts(&file);
        assert!(
            code.contains("let __list ="),
            "expected binding `let __list = ...` inside the print, was:\n{}",
            code
        );
        // The header `[` is emitted as Str literal inside the format.
        assert!(
            code.contains("String :: from (\"[\")"),
            "expected `String::from(\"[\")` as list header, was:\n{}",
            code
        );
    }

    #[test]
    fn print_of_map_emits_iter_inline_with_braces() {
        let file = ast_test::parse(&gen("let m: Map<Str, Int> = {\"a\": 1}\nprint(m)").unwrap());
        let stmts = ast_test::main_block_stmts(&file);
        assert!(
            ast_test::count_macro_calls(stmts, "println") >= 1,
            "expected at least one println! to print m"
        );
        let code = ast_test::ts(&file);
        assert!(
            code.contains("let __map ="),
            "expected binding `let __map = ...` inside the print, was:\n{}",
            code
        );
        assert!(
            code.contains("String :: from (\"{\")"),
            "expected `String::from(\"{{\")` as map header, was:\n{}",
            code
        );
    }

