    #[test]
    fn codegen_emits_struct_fitz_secret_in_prelude() {
        // The prelude always emits __FitzSecret<T> + impls; rustc
        // does dead-code elim if unused.
        let src = "let x = 42";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        assert!(
            code.contains("pub struct __FitzSecret<T>(T)"),
            "expected struct __FitzSecret in the prelude"
        );
        assert!(
            code.contains("fn expose(self) -> T"),
            "expected method expose() in __FitzSecret"
        );
        assert!(
            code.contains("write!(f, \"<redacted Secret>\")"),
            "expected redacted Display/Debug in __FitzSecret"
        );
    }

    #[test]
    fn codegen_secret_builtin_calls_fitz_secret_helper() {
        let src = "fn main() => 0\n\
                   let _ = secret(\"KEY\")";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        assert!(
            code.contains("__fitz_secret(&"),
            "expected call to __fitz_secret(&...)"
        );
        // The builtin helper must exist in the prelude.
        assert!(
            code.contains("fn __fitz_secret(key: &str)"),
            "expected helper __fitz_secret in prelude"
        );
    }

    #[test]
    fn codegen_config_int_emits_parse_inline() {
        // config with Int default must emit an inline block with
        // parse::<i64>() and fallback to the default.
        let src = "let port: Int = config(\"PORT\", 8080)";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        assert!(
            code.contains("let __default: i64 = 8080"),
            "expected binding __default typed Int"
        );
        assert!(
            code.contains(".parse::<i64>()"),
            "expected parse::<i64>() for Int coercion"
        );
    }

    #[test]
    fn codegen_config_bool_emits_match_inline() {
        let src = "let flag: Bool = config(\"FLAG\", false)";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        assert!(
            code.contains("let __default: bool = false"),
            "expected binding __default typed Bool"
        );
        // The match must accept the documented variants.
        assert!(
            code.contains("\"true\" | \"1\" | \"yes\" | \"on\""),
            "expected match with truthy variants"
        );
    }

    #[test]
    fn codegen_secret_expose_emits_rust_method() {
        // `s.expose()` must translate to `(<s>).expose()` Rust.
        let src = "fn run() -> Result<Str> {\n\
                   let s = secret(\"K\")?\n\
                   let exposed: Str = s.expose()\n\
                   return Ok(exposed)\n\
                   }\n\
                   print(run())";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        assert!(
            code.contains(".expose()"),
            "expected call to .expose() in the Rust output"
        );
    }

    #[test]
    fn codegen_secret_unknown_method_is_error() {
        // The checker rejects at compile-time; codegen has a
        // defensive barrier in case the checker is disabled (-no-typecheck).
        // gen_ignoring_check forces codegen to see it.
        let src = "fn run() -> Result<Null> {\n\
                   let s = secret(\"K\")?\n\
                   let _ = s.unwrap()\n\
                   return Ok(null)\n\
                   }";
        let err = gen_ignoring_check(src).unwrap_err();
        assert!(
            err.message.contains(".expose()"),
            "expected message citing .expose(), was: {}",
            err.message
        );
    }

    #[test]
    fn codegen_emits_draining_state_and_shutdown_signal_for_http() {
        // Any HTTP program emits the health checks + shutdown signal
        // preamble, even without @healthz/@readyz declared.
        let src = "@server(3000) fn main() => 0\n\
                   @get(\"/\") fn index() -> Str => \"ok\"";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        assert!(
            code.contains("static __FITZ_DRAINING"),
            "expected `static __FITZ_DRAINING` in the output"
        );
        assert!(
            code.contains("async fn __fitz_shutdown_signal"),
            "expected `async fn __fitz_shutdown_signal` in the output"
        );
        assert!(
            code.contains(".with_graceful_shutdown(__fitz_shutdown_signal("),
            "expected `with_graceful_shutdown` in the axum::serve line"
        );
    }

    #[test]
    fn codegen_default_healthz_and_readyz_mount_without_user_handlers() {
        // Without @healthz/@readyz declared, the routes are mounted with
        // the default wrappers (__fitz_default_healthz/readyz).
        let src = "@server(3000) fn main() => 0\n\
                   @get(\"/\") fn index() -> Str => \"ok\"";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        assert!(
            code.contains(".route(\"/healthz\", axum::routing::get(__fitz_default_healthz))"),
            "expected /healthz route with default handler"
        );
        assert!(
            code.contains(".route(\"/readyz\", axum::routing::get(__fitz_default_readyz))"),
            "expected /readyz route with default handler"
        );
        // The default wrappers must exist.
        assert!(
            code.contains("async fn __fitz_default_healthz"),
            "expected `async fn __fitz_default_healthz`"
        );
        assert!(
            code.contains("async fn __fitz_default_readyz"),
            "expected `async fn __fitz_default_readyz`"
        );
    }

    #[test]
    fn codegen_user_healthz_bool_emits_wrapper_with_correct_mapping() {
        // @healthz fn liveness() -> Bool { ... } must generate:
        // - wrapper `__fitz_user_healthz` that calls liveness() sync
        // - if/else mapping Bool → ok/unhealthy
        let src = "@server(3000) fn main() => 0\n\
                   @get(\"/\") fn idx() -> Str => \"x\"\n\
                   @healthz fn liveness() -> Bool { return true }";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        assert!(
            code.contains("async fn __fitz_user_healthz"),
            "expected wrapper `__fitz_user_healthz`"
        );
        assert!(
            code.contains("let __r: bool = liveness();"),
            "expected sync invocation `liveness()` with bool type"
        );
        assert!(
            code.contains("if __r { __fitz_health_ok() } else { __fitz_health_unhealthy(None) }"),
            "expected if/else Bool → ok/unhealthy mapping"
        );
        assert!(
            code.contains(".route(\"/healthz\", axum::routing::get(__fitz_user_healthz))"),
            "expected route to point to the user wrapper instead of the default"
        );
    }

    #[test]
    fn codegen_user_readyz_result_null_emits_draining_check_and_match() {
        // @readyz fn readiness() -> Result<Null> { ... } must generate:
        // - draining check BEFORE the invoke (during shutdown fixed 503)
        // - match Ok(())/Err mapping
        let src = "@server(3000) fn main() => 0\n\
                   @get(\"/\") fn idx() -> Str => \"x\"\n\
                   @readyz fn readiness() -> Result<Null> { return Ok(null) }";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        assert!(
            code.contains("async fn __fitz_user_readyz"),
            "expected wrapper `__fitz_user_readyz`"
        );
        // The draining check must appear inside the user wrapper
        // (before the call to readiness()).
        let wrapper_start = code
            .find("async fn __fitz_user_readyz")
            .expect("wrapper user_readyz");
        let wrapper_section = &code[wrapper_start..wrapper_start + 800];
        assert!(
            wrapper_section.contains("__FITZ_DRAINING.load"),
            "expected __FITZ_DRAINING check inside the user readyz wrapper"
        );
        assert!(
            code.contains("let __r: Result<(), String> = readiness();"),
            "expected type `Result<(), String>` for Result<Null>"
        );
        assert!(
            code.contains("Ok(()) => __fitz_health_ok()"),
            "expected match Ok(()) → ok"
        );
    }

