    #[test]
    fn query_params_required_emits_match_some_404_if_missing() {
        // `@get("/x?limit={limit}") fn h(limit: Int)`: the wrapper
        // extracts `Query<HashMap>` and binds `limit: i64` with coercion.
        // Missing → 400.
        let src = "@get(\"/items?limit={limit}\") fn list_items(limit: Int) -> Int => limit";
        let code = gen(src).unwrap();
        let file = ast_test::parse(&code);
        let wrapper = ast_test::find_item_fn(&file, "__handler_list_items")
            .expect("missing __handler_list_items");
        let pats_tys = ast_test::fn_param_pats_and_types(wrapper);
        assert!(
            pats_tys.iter().any(|(p, t)| {
                p.contains("axum :: extract :: Query")
                    && p.contains("__qmap")
                    && t.contains("axum :: extract :: Query")
                    && t.contains("HashMap")
                    && t.contains("String")
            }),
            "expected extractor Query<HashMap<String, String>>, got: {:?}",
            pats_tys
        );
        let limit =
            ast_test::find_local_in_fn(wrapper, "limit").expect("missing `let limit` in wrapper");
        assert_eq!(
            ast_test::local_type(&limit).as_deref(),
            Some("i64"),
            "expected `limit: i64`"
        );
        let init = ast_test::local_init(&limit).unwrap_or_default();
        assert!(
            init.contains("__qmap . get (\"limit\")") || init.contains("__qmap .get (\"limit\")"),
            "expected init matching __qmap.get(\"limit\"), got: {}",
            init
        );
        // The error message for missing query is a user-visible contract,
        // I check it on the full code.
        assert!(
            code.contains("query param 'limit': missing — is required"),
            "expected 400 message for missing query param"
        );
    }

