    #[test]
    fn http_body_post_with_type_emits_from_fitz_json() {
        // Mini-batch UC: the extractor switched from `axum::Json<serde_json::Value>`
        // to `axum::body::Bytes` to dispatch by Content-Type
        // (JSON vs urlencoded vs 415) inside the wrapper.
        let src = "type Input { msg: Str }\n\
                   @post(\"/echo\") fn echo(body: Input) -> Input => body";
        let code = gen(src).unwrap();
        let file = ast_test::parse(&code);
        let wrapper =
            ast_test::find_item_fn(&file, "__handler_echo").expect("missing __handler_echo");
        let pats_tys = ast_test::fn_param_pats_and_types(wrapper);
        assert!(
            pats_tys.iter().any(|(p, t)| {
                p.contains("body_body_bytes") && t.contains("axum :: body :: Bytes")
            }),
            "expected extractor body_body_bytes: axum::body::Bytes, got: {:?}",
            pats_tys
        );
        let body = ast_test::fn_body_text(wrapper);
        assert!(
            body.contains("__FromFitzJson") && body.contains("__from_fitz_json"),
            "expected body to call __from_fitz_json, got:\n{}",
            body
        );
        assert!(
            body.contains("StatusCode :: BAD_REQUEST"),
            "expected 400 if deserialization fails, got:\n{}",
            body
        );
    }

    #[test]
    fn uc_http_body_extracts_bytes_not_json() {
        // Mini-batch UC: we confirm the body extractor is
        // Bytes, not Json<Value>. This is what enables the
        // Content-Type dispatch inside the wrapper.
        let src = "type Input { msg: Str }\n\
                   @post(\"/echo\") fn echo(body: Input) -> Input => body";
        let code = gen(src).unwrap();
        assert!(
            code.contains("body_body_bytes: axum::body::Bytes"),
            "expected extractor `body_body_bytes: axum::body::Bytes`, not found"
        );
        assert!(
            !code.contains("axum::Json(body_raw):"),
            "did not expect the old extractor `axum::Json(body_raw): axum::Json<serde_json::Value>`"
        );
    }

    #[test]
    fn uc_http_body_dispatches_by_content_type() {
        // Mini-batch UC: the wrapper computes ct_primary and dispatches
        // between JSON, urlencoded and 415.
        let src = "type Input { msg: Str }\n\
                   @post(\"/echo\") fn echo(body: Input) -> Input => body";
        let code = gen(src).unwrap();
        assert!(
            code.contains("body_ct_primary"),
            "expected bind `body_ct_primary` for Content-Type"
        );
        assert!(
            code.contains("\"application/json\""),
            "expected branch for `application/json`"
        );
        assert!(
            code.contains("\"application/x-www-form-urlencoded\""),
            "expected branch for urlencoded"
        );
        assert!(
            code.contains("__parse_urlencoded"),
            "expected call to `__parse_urlencoded` for urlencoded"
        );
        assert!(
            code.contains("UNSUPPORTED_MEDIA_TYPE"),
            "expected 415 for unsupported Content-Type"
        );
    }

    #[test]
    fn uc_http_body_415_msg_matches_interpreter() {
        // Mini-batch HA + MP-Build — the codegen 415 msg
        // contains the key phrases the user expects to see, and
        // cites the 3 supported CTs (JSON, urlencoded, multipart)
        // exactly like the interpreter (`http::handle_task`).
        let src = "type Input { msg: Str }\n\
                   @post(\"/echo\") fn echo(body: Input) -> Input => body";
        let code = gen(src).unwrap();
        let key_phrases = [
            "Content-Type not supported",
            "application/json",
            "application/x-www-form-urlencoded",
            "multipart/form-data",
            "future sub-step",
        ];
        for phrase in &key_phrases {
            assert!(
                code.contains(phrase),
                "expected the 415 msg to contain `{}`, not found",
                phrase
            );
        }
    }

