    // ---- Mini-batch Lt — let-destructure with rich sub-patterns ----

    #[test]
    fn lt_let_pure_irrefutable_emits_direct_path() {
        // Classic case `let (a, b) = ...`: codegen does NOT use match
        // wrapper. Emits `let (a, b) = ...;` directly (pre-Lt path).
        let code = gen("let (a, b) = (1, 2)\nprint(a)\nprint(b)\n").unwrap();
        assert!(
            !code.contains("__destr_scrut"),
            "expected pure path (without __destr_scrut) for Ident/Tuple, got:\n{}",
            code
        );
        assert!(
            code.contains("let (a, b)"),
            "expected direct `let (a, b)`, got:\n{}",
            code
        );
    }

    #[test]
    fn lt_let_literal_int_subpattern_emits_match_wrapper() {
        // `let (1, x) = ...`: refutable → match wrapper with catch-all
        // panic. The `x` name is declared in the outer scope.
        let code = gen("let (1, x) = (1, 42)\nprint(x)\n").unwrap();
        assert!(
            code.contains("__destr_scrut"),
            "expected match wrapper (with __destr_scrut), got:\n{}",
            code
        );
        assert!(
            code.contains("panic!(\"destructuring did not match the value"),
            "expected catch-all panic, got:\n{}",
            code
        );
        assert!(
            code.contains("(1i64, x)"),
            "expected pattern `(1i64, x)`, got:\n{}",
            code
        );
    }

    #[test]
    fn lt_let_ok_binding_subpattern_extracts_result() {
        // `let (Ok(v), tag) = ...`: bindings = [v, tag].
        let code = gen("let (Ok(v), tag) = (Ok(99), \"result\")\nprint(v)\nprint(tag)\n").unwrap();
        assert!(
            code.contains("__destr_scrut"),
            "expected match wrapper, got:\n{}",
            code
        );
        assert!(
            code.contains("(Ok(v), tag)"),
            "expected pattern `(Ok(v), tag)`, got:\n{}",
            code
        );
        // Both bindings are emitted in the arm's return tuple.
        assert!(
            code.contains("(v, tag)"),
            "expected return `(v, tag)`, got:\n{}",
            code
        );
    }

    #[test]
    fn lt_let_str_literal_subpattern_uses_inline_guard() {
        // `let ("ada", n) = ...`: the Str literal generates a guard
        // `__s_X.as_str() == "ada"` in the match arm.
        let code = gen("let (\"ada\", n) = (\"ada\", 7)\nprint(n)\n").unwrap();
        assert!(
            code.contains("__destr_scrut"),
            "expected match wrapper, got:\n{}",
            code
        );
        assert!(
            code.contains("if __s_") && code.contains(".as_str() == \"ada\""),
            "expected guard on __s_X.as_str(), got:\n{}",
            code
        );
    }

    #[test]
    fn lt_let_range_subpattern_uses_guard_contains() {
        // `let (0..100, y) = ...`: Range emits guard `(0..100).contains(&__n_X)`.
        let code = gen("let (0..100, y) = (50, \"yes\")\nprint(y)\n").unwrap();
        assert!(
            code.contains(".contains(&__n_"),
            "expected guard `(0..100).contains(&__n_X)`, got:\n{}",
            code
        );
    }

    #[test]
    fn lt_let_single_binding_does_not_emit_paren() {
        // With a single binding, `let mut <name> = match ...` avoids
        // the degenerate tuple `(x,)` that would require a trailing comma.
        let code = gen("let (1, x) = (1, 42)\nprint(x)\n").unwrap();
        assert!(
            code.contains("let mut x = match"),
            "expected `let mut x = match ...` (without parens), got:\n{}",
            code
        );
    }

    // ---- Mini-batch El — Err(List<T>) / Err(Map<K,V>) in codegen ----

    /// Test helper: extracts the body of fn `fail` from the codegen
    /// output to make precise assertions. The full output includes
    /// prelude + internal helpers that may use `Err(format!(...))`
    /// legitimately (e.g., `__fitz_env`); assertions on the specific
    /// `fail` fn filter that noise out.
    fn extract_fail_body(code: &str) -> String {
        let idx = code
            .find("fn fail")
            .expect("`fn fail` not found in the output");
        // Take up to the next `fn ` that is not `fn fail`. Lean:
        // it's enough to cut at the next "\nfn " that would start a
        // different fn.
        let rest = &code[idx..];
        let end = rest[5..].find("\nfn ").map(|p| p + 5).unwrap_or(rest.len());
        rest[..end].to_string()
    }

    #[test]
    fn el_err_list_is_emitted_without_coercion_to_string() {
        // Pre-El: `Err([1,2,3])` with `Result<Int, List<Int>>` was
        // rejected with codegen error. Post-El: emits `Err(<list>)`
        // directly with `Arc<Mutex<Vec<i64>>>` intact, without coercion
        // to String.
        let code = gen("fn fail() -> Result<Int, List<Int>> {\n\
                 return Err([1, 2, 3])\n\
             }\n\
             fail()")
        .unwrap();
        let fail_body = extract_fail_body(&code);
        assert!(
            !fail_body.contains("Err(format!"),
            "expected List to be emitted directly, not via format!; got:\n{}",
            fail_body
        );
        assert!(
            code.contains("Err(Arc::new(Mutex::new(vec!["),
            "expected `Err(Arc::new(Mutex::new(vec![...])))`, got:\n{}",
            code
        );
        assert!(
            code.contains("Result<i64, Arc<Mutex<Vec<i64>>>>"),
            "expected return type `Result<i64, Arc<Mutex<Vec<i64>>>>`, got:\n{}",
            code
        );
    }

    #[test]
    fn el_err_map_is_emitted_directly() {
        let code = gen("fn fail() -> Result<Int, Map<Str, Int>> {\n\
                 return Err({\"a\": 1, \"b\": 2})\n\
             }\n\
             fail()")
        .unwrap();
        let fail_body = extract_fail_body(&code);
        assert!(
            !fail_body.contains("Err(format!"),
            "Map should not go via format!; got:\n{}",
            fail_body
        );
        assert!(
            code.contains("Result<i64, Arc<Mutex<Vec<(String, i64)>>>>"),
            "expected return type `Result<i64, Map>`, got:\n{}",
            code
        );
    }

    #[test]
    fn f15_module_loader_accepts_transitive_imports_in_module() {
        // F15: a module with its own `import` is no longer rejected at
        // codegen-time. The test uses `generate_project` indirectly
        // via the e2e suite; here we just validate at unit level that
        // `gen_module` (which does NOT take a loader) still works with
        // import stmts in the AST — the stmts are ignored (already
        // processed by the loader).
        let code = gen_module("from segundo import dos\nfn x() -> Int => dos()");
        assert!(
            code.is_err(),
            "gen_module without loader: the body of `x` references `dos` \
             which is not in scope; must be an error"
        );
        // The message should NOT mention 5b.5 or "imports transitivos".
        let msg = code.unwrap_err().message;
        assert!(
            !msg.contains("transitive") && !msg.contains("5b.5"),
            "error must no longer cite transitive debt post-F15; was: {}",
            msg
        );
    }

