    // v0.15.14 — URGENTE-1 codegen path: the binary produced by
    // `fitz build` with N `@cron(store=db)` also needs the OnceCell
    // that serializes the first init of the tables, otherwise N parallel
    // jobs hit the Postgres pg_type catalog race at boot.
    // Bit-a-bit parallel to the fix in `src/cron_jobs.rs::INIT_STORAGE_ONCE`
    // of the interpreter (v0.15.13 only covered `fitz run`).
    #[test]
    fn v0_15_14_codegen_cron_persistent_emits_oncecell_for_init_storage() {
        // Program with persistent @cron — forces emission of the
        // SQL_HELPERS_PRELUDE that contains `__fitz_cron_init_storage`.
        let src = "let db_result = db.connect(\"postgres://test\").await\n\
                   @cron(\"0 0 * * *\", store=db_result)\n\
                   async fn cleanup() -> Result<Null> { return Ok(null) }\n\
                   @cron(\"0 0 3 * * *\", store=db_result)\n\
                   async fn another() -> Result<Null> { return Ok(null) }\n\
                   @server(8080)\n\
                   fn main() => 0\n";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));

        // The prelude must contain the global OnceCell.
        assert!(
            code.contains("__FITZ_CRON_INIT_STORAGE_ONCE")
                && code.contains("tokio::sync::OnceCell"),
            "expected `static __FITZ_CRON_INIT_STORAGE_ONCE: tokio::sync::OnceCell<...>` in the prelude, got code length {}",
            code.len()
        );

        // The `__fitz_cron_init_storage` wrapper must call `get_or_init`.
        assert!(
            code.contains("__FITZ_CRON_INIT_STORAGE_ONCE") && code.contains("get_or_init"),
            "expected wrapper that calls `get_or_init` on the OnceCell, got code length {}",
            code.len()
        );

        // The real inner was renamed to `__fitz_cron_init_storage_inner`.
        assert!(
            code.contains("__fitz_cron_init_storage_inner"),
            "expected inner helper `__fitz_cron_init_storage_inner` that performs the real CREATE TABLE"
        );
    }

