    #[test]
    fn v0_15_11_cron_store_kwarg_with_state_var_materializes_local_before_spawn() {
        // v0.15.11 — Regression of bug discovered in TaskHub boilerplate.
        // When `@cron(..., store=X)` references a top-level binding that
        // SOME handler also consumes (typical case: `let db_result =
        // db.connect(...).await` used by HTTP handlers and crons),
        // codegen hoists it to `static __FITZ_STATE_DB_RESULT`. The
        // spawn block in `__main_inner` references `db_result` by user
        // name — needs local materialization prior to the spawn.
        //
        // v0.15.12 — the init contains `.await` → state var goes from
        // `LazyLock` to `tokio::sync::OnceCell`. Local materialization
        // changes from `(*X).clone()` to `X.get().expect(...).clone()`.
        let src = "let db_result = db.connect(env_or(\"DATABASE_URL\", \"\")).await\n\
                   @cron(\"0 0 * * *\", store=db_result)\n\
                   async fn cleanup() -> Result<Null> { return Ok(null) }\n\
                   @get(\"/healthz\")\n\
                   async fn healthz() -> Str {\n\
                       let _ = db_result\n\
                       return \"ok\"\n\
                   }\n\
                   @server(8080)\n\
                   fn main() => 0\n";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // The state var must have been hoisted to a static (OnceCell post-v0.15.12).
        assert!(
            code.contains("static __FITZ_STATE_DB_RESULT"),
            "expected state var hoisted to `static __FITZ_STATE_DB_RESULT`"
        );
        // Local materialization must come BEFORE the spawn block.
        let materialize_idx = code.find("let db_result: Result<__FitzDbConn, String> = __FITZ_STATE_DB_RESULT.get()")
            .or_else(|| code.find("let db_result"))
            .expect("expected `let db_result = __FITZ_STATE_DB_RESULT.get().expect(...).clone();` in __main_inner");
        let spawn_idx = code
            .find("tokio::spawn(__fitz_run_cron_job")
            .expect("expected `tokio::spawn(__fitz_run_cron_job(...))` in __main_inner");
        assert!(
            materialize_idx < spawn_idx,
            "expected materialization of `db_result` to precede the cron spawn"
        );
        // The spawn must use the local name (not the static directly).
        assert!(
            code.contains("(&db_result).into_store()"),
            "expected `(&db_result).into_store()` after materialization"
        );
    }

    #[test]
    fn v0_15_12_state_var_with_await_uses_oncecell_and_init_eager() {
        // v0.15.12 — Pre-existing bug from TaskHub: `let db_result =
        // db.connect(url).await` top-level with HTTP handlers that
        // consume it hoisted to `LazyLock<T> = LazyLock::new(|| init)`
        // where init contained `.await` → rustc E0728: `await` is only
        // allowed inside `async` functions and blocks.
        //
        // Fix: detect `.await` in the RHS via `expr_contains_await`,
        // emit `tokio::sync::OnceCell::const_new()` for the static
        // and initialize eagerly in the `async fn main()` body.
        let src = "let db = db.connect(\"postgres://x\").await\n\
                   @get(\"/healthz\")\n\
                   async fn healthz() -> Str {\n\
                       let _ = db\n\
                       return \"ok\"\n\
                   }\n\
                   @server(8080)\n\
                   fn main() => 0\n";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // 1) The static must be OnceCell (not LazyLock).
        assert!(
            code.contains("static __FITZ_STATE_DB : tokio :: sync :: OnceCell")
                || code.contains("static __FITZ_STATE_DB: tokio::sync::OnceCell"),
            "expected `static __FITZ_STATE_DB: tokio::sync::OnceCell<...>`, got:\n{}",
            code
        );
        // 2) The eager init with `.set(...)` must be in the body of main.
        assert!(
            code.contains("__FITZ_STATE_DB.set(__init)")
                || code.contains("__FITZ_STATE_DB . set (__init)"),
            "expected `__FITZ_STATE_DB.set(__init).expect(...)` in the body of async fn main(), got:\n{}",
            code
        );
        // 3) Materialization in the handler must use `get().expect(...).clone()`.
        assert!(
            code.contains("__FITZ_STATE_DB.get()") || code.contains("__FITZ_STATE_DB . get ()"),
            "expected `__FITZ_STATE_DB.get().expect(...).clone()` in the handler body, got:\n{}",
            code
        );
        // 4) The old LazyLock pattern with .await inside must NOT remain
        //    (the original bug).
        assert!(
            !code.contains("LazyLock::new(|| (__fitz_db_connect"),
            "expected NO LazyLock with `.await` inside (bug regression), got:\n{}",
            code
        );
    }

    #[test]
    fn v0_15_12_state_var_without_await_keeps_using_lazylock() {
        // v0.15.12 — the canonical LazyLock path is preserved when the
        // init does NOT contain `.await`. Typical case: HTTP state with a
        // shared list (`let users = []`).
        let src = "let users: List<Str> = []\n\
                   @get(\"/users\")\n\
                   fn list_users() -> List<Str> {\n\
                       return users\n\
                   }\n\
                   @server(8080)\n\
                   fn main() => 0\n";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // The LazyLock path is preserved (not an async init).
        assert!(
            code.contains("static __FITZ_STATE_USERS : std :: sync :: LazyLock")
                || code.contains("static __FITZ_STATE_USERS: std::sync::LazyLock"),
            "expected `static __FITZ_STATE_USERS: std::sync::LazyLock<...>`, got:\n{}",
            code
        );
        // Old materialization as well.
        assert!(
            code.contains("(*__FITZ_STATE_USERS).clone()")
                || code.contains("(* __FITZ_STATE_USERS) . clone ()"),
            "expected `(*__FITZ_STATE_USERS).clone()` (sync path), got:\n{}",
            code
        );
    }

    #[test]
    fn v0_15_12_expr_contains_await_detects_nested_await() {
        // Smoke test of the `expr_contains_await` helper. Covers the
        // canonical cases: direct await, await inside Try, await inside
        // Call.callee/args, await inside BinOp/UnaryOp.
        use crate::lexer::tokenize;
        use crate::parser::parse;

        fn extract_first_assign_value(src: &str) -> Expr {
            let tokens = tokenize(src).expect("lex");
            let program = parse(tokens).expect("parse");
            for stmt in &program {
                if let Stmt::Assign { value, .. } = stmt {
                    return value.clone();
                }
            }
            panic!("did not find Stmt::Assign in: {}", src);
        }

        // True cases
        let cases_await = [
            "let x = foo().await",      // direct
            "let x = (foo()?).await",   // inside Try
            "let x = bar(foo().await)", // inside Call.args
            "let x = foo().await + 1",  // inside BinOp.left
            "let x = 1 + foo().await",  // inside BinOp.right
            "let x = -foo().await",     // inside UnaryOp
        ];
        for src in cases_await {
            let value = extract_first_assign_value(src);
            assert!(
                expr_contains_await(&value),
                "expected `{}` to contain .await",
                src
            );
        }

        // False cases (no .await)
        let cases_no_await = [
            "let x = 42",
            "let x = foo()",
            "let x = foo() + bar()",
            "let x = [1, 2, 3]",
        ];
        for src in cases_no_await {
            let value = extract_first_assign_value(src);
            assert!(
                !expr_contains_await(&value),
                "expected `{}` NOT to contain .await",
                src
            );
        }
    }

    #[test]
    fn v0_15_12_spawn_clones_outer_vars_before_async_move() {
        // v0.15.12 — Pre-existing bug from TaskHub: when the inner
        // call of `spawn(...)` references a var from the outer scope that
        // the caller also uses afterwards, `tokio::spawn`'s `async move`
        // moves the var and the caller breaks with E0382.
        //
        // Fix: identify local scope idents in inner_args
        // and emit `let <name> = <name>.clone();` BEFORE the
        // `tokio::spawn(async move { ... })`. The shadow is captured
        // by the closure; the outer scope stays accessible.
        let src = "@background\n\
                   async fn send_due_reminder(id: Int) -> Null { return null }\n\
                   async fn caller(new_id: Int) -> Int {\n\
                       let _ = spawn(send_due_reminder(new_id))\n\
                       return new_id\n\
                   }\n\
                   print(\"hi\")";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // The shadow `let new_id = new_id.clone();` must appear BEFORE
        // `tokio::spawn(async move`.
        let shadow_idx = code
            .find("let new_id = new_id . clone ()")
            .or_else(|| code.find("let new_id = new_id.clone()"))
            .expect("expected shadow `let new_id = new_id.clone()` before spawn");
        let spawn_idx = code
            .find("tokio :: spawn (async move")
            .or_else(|| code.find("tokio::spawn(async move"))
            .expect("expected `tokio::spawn(async move ...)`");
        assert!(
            shadow_idx < spawn_idx,
            "expected shadow clone to precede tokio::spawn"
        );
    }

    #[test]
    fn v0_15_12_spawn_without_args_does_not_emit_shadow_clones() {
        // Without args, there is nothing to shadow — codegen must not
        // emit empty clones or anything odd.
        let src = "@background\n\
                   fn beat() -> Null { return null }\n\
                   async fn caller() -> Null {\n\
                       let _ = spawn(beat())\n\
                       return null\n\
                   }\n\
                   print(\"hi\")";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // The spawn is still there, without pre-clones.
        assert!(
            code.contains("tokio :: spawn (async move") || code.contains("tokio::spawn(async move"),
            "expected `tokio::spawn(async move ...)`, got:\n{}",
            code
        );
    }

    #[test]
    fn v0_15_12_spawn_does_not_clone_idents_that_are_named_fns() {
        // If the arg is a top-level fn (`@background`), its name
        // must NOT appear as a shadow clone — it is not a local var
        // of the scope. The `var_in_any_scope` filter discards
        // fn names.
        let src = "@background\n\
                   fn helper(n: Int) -> Int { return n }\n\
                   @background\n\
                   async fn job(n: Int) -> Int { return helper(n) }\n\
                   async fn caller() -> Int {\n\
                       let _ = spawn(job(42))\n\
                       return 0\n\
                   }\n\
                   print(\"hi\")";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // `job` must NOT be shadowed (it's a fn, not a var).
        assert!(
            !code.contains("let job = job . clone ()") && !code.contains("let job = job.clone()"),
            "did not expect shadow clone of fn name `job`, got:\n{}",
            code
        );
    }

    #[test]
    fn spawn_call_emits_tokio_spawn_and_box_pin() {
        let src = "@background\nfn job() -> Int { return 42 }\n\
                   async fn caller() -> Int {\n\
                       let f = spawn(job())\n\
                       return f.await\n\
                   }\n\
                   print(\"hi\")";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        assert!(
            code.contains("tokio::spawn"),
            "expected `tokio::spawn` in the codegen of spawn(...), got:\n{}",
            code
        );
        assert!(
            code.contains("Box::pin"),
            "expected `Box::pin` wrapping the JoinHandle in Future<T>"
        );
    }

    #[test]
    fn background_decorator_does_not_emit_extra_code() {
        // `@background` is a checker marker; in codegen the fn is
        // emitted as a normal `pub fn` with no visible difference.
        let src = "@background\nfn send(addr: Str) -> Null { return null }\n\
                   print(\"hi\")";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        assert!(
            code.contains("fn send"),
            "expected fn defined the same as without decorator"
        );
    }

