    #[test]
    fn ok_propagation_coerce_pyany_to_str_inside_return_ok() {
        // v0.9.53 8.7-ok-propagation — `return Ok(json.dumps(...)?)`
        // inside fn `-> Result<Str>` previously failed in rustc with
        // `expected String, found __FitzPyObject` because `gen_ok`
        // returned `Result<PyAny>` without coercion to the expected `Str` and
        // the general `coerce` does not handle `Result<A> → Result<B>`.
        // Post-fix: `gen_return` detects `Expr::Ok(inner)` when
        // ret_expected is `Result<T>` and coerces `inner` directly to T
        // (here PyAny → Str via __fitz_py_extract_string).
        let src = "from python import json\n\
                   fn parse(raw: Str) -> Result<Str> {\n  \
                       return Ok(json.dumps(raw)?)\n\
                   }";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // The return must coerce inner via __fitz_py_extract_string,
        // NOT emit the wrapped Ok without coercion.
        assert!(
            code.contains("__fitz_py_extract_string"),
            "expected __fitz_py_extract_string inside return Ok, output:\n{}",
            code
        );
    }

    #[test]
    fn ok_propagation_coerce_pyany_to_int_inside_return_ok() {
        // Variant: PyAny → Int (via __fitz_py_extract_i64).
        let src = "from python import math\n\
                   fn answer() -> Result<Int> {\n  \
                       return Ok(math.floor(42.5)?)\n\
                   }";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        assert!(
            code.contains("__fitz_py_extract_i64"),
            "expected __fitz_py_extract_i64 inside return Ok, output:\n{}",
            code
        );
    }

    #[test]
    fn ok_propagation_inner_already_correct_does_not_emit_unnecessary_coerce() {
        // Sanity: if `inner` already types to the expected `T`, must not emit
        // coerce (`coerce` returns the code as-is when `from == to`).
        // The return becomes `return Ok(<inner code>);` without extra wrapping.
        let src = "type T { v: Int }\n\
                   fn make() -> Result<T> {\n  \
                       return Ok(T { v: 1 })\n\
                   }";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // The fix must NOT add `__fitz_py_extract_*` or additional
        // wrappers — inner is already pure `T`.
        assert!(
            !code.contains("__fitz_py_extract"),
            "did NOT expect __fitz_py_extract for inner already correctly typed, output:\n{}",
            code
        );
        // The return exists (with the expected shape).
        assert!(
            code.contains("return Ok("),
            "expected `return Ok(...)` in the body, output:\n{}",
            code
        );
    }

