    #[test]
    fn py_await_split_emits_fitz_py_await_obj() {
        // Split pattern: the coroutine is bound, then awaited.
        //   let fut = asyncio.sleep(1)?    // fut: PyAny (the coro)
        //   let _ = fut.await              // `__fitz_py_await_obj` applies
        //
        // Before the fix, codegen emitted `(fut).await` which broke Rust
        // because `__FitzPyObject` does not impl `IntoFuture`. Now it detects
        // `inner_ty == PyAny` and dispatches to the dedicated helper.
        let src = "from python import asyncio\n\
                   async fn run() -> Result<Null> {\n\
                       let fut = asyncio.sleep(1)?\n\
                       let _ = fut.await\n\
                       return Ok(null)\n\
                   }";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // The helper is emitted when uses_async + uses_python.
        assert!(
            code.contains("async fn __fitz_py_await_obj"),
            "expected helper `__fitz_py_await_obj` in the prelude"
        );
        // The call site uses the helper.
        assert!(
            code.contains("__fitz_py_await_obj(&"),
            "expected `__fitz_py_await_obj(&fut).await?` in the body of run, output: ...{}...",
            &code[code.len().saturating_sub(2000)..]
        );
    }

    #[test]
    fn py_await_inline_keeps_using_invoke_await() {
        // Sanity: the inline `py_call()?.await` pattern still emits
        // `__fitz_py_invoke_await(...)` (original combined helper) and
        // is NOT contaminated with `__fitz_py_await_obj`.
        let src = "from python import asyncio\n\
                   async fn run() -> Result<Null> {\n\
                       let _ = asyncio.sleep(1)?.await\n\
                       return Ok(null)\n\
                   }";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // Inline combined helper.
        assert!(
            code.contains("__fitz_py_invoke_await("),
            "expected `__fitz_py_invoke_await` in the body (inline path)"
        );
    }

