    #[test]
    fn ws_codegen_emits_asyncapi_ui_handler_and_route() {
        let src = "@server(43978)\n\
                   fn main() => 0\n\
                   @ws(\"/chat\")\n\
                   async fn chat(conn: WsConn<Str>) -> Null { return null }";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // UI handler defined.
        assert!(
            code.contains("async fn __serve_asyncapi("),
            "expected `async fn __serve_asyncapi()` in the output"
        );
        // The static with the embedded HTML.
        assert!(
            code.contains("__FITZ_ASYNCAPI_HTML"),
            "expected embedded `__FITZ_ASYNCAPI_HTML` static"
        );
        // Auto-registered route in the router.
        assert!(
            code.contains(".route(\"/asyncapi\", axum::routing::get(__serve_asyncapi))"),
            "expected route `/asyncapi` in the codegen output router"
        );
        // The embedded HTML references the schema endpoint.
        assert!(
            code.contains("/asyncapi.json"),
            "expected embedded HTML to reference /asyncapi.json"
        );
    }

    #[test]
    fn ws_codegen_asyncapi_ui_yields_if_user_declares_handler() {
        // If the user declared their own `@get("/asyncapi")`, the
        // auto-register yields (the user's wins).
        let src = "@server(43979)\n\
                   fn main() => 0\n\
                   @ws(\"/chat\")\n\
                   async fn chat(conn: WsConn<Str>) -> Null { return null }\n\
                   @get(\"/asyncapi\")\n\
                   fn custom() -> Str => \"mi-ui-custom\"";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // The user's handler is present.
        assert!(code.contains("async fn __handler_custom"));
        // The auto-register handler is also emitted (we don't
        // condition its emission on user_paths, only the registration),
        // but the route `.route("/asyncapi", ...)` with `__serve_asyncapi`
        // must NOT appear (because the user wins).
        assert!(
            !code.contains(".route(\"/asyncapi\", axum::routing::get(__serve_asyncapi))"),
            "auto-register of /asyncapi should not be present when user declares it"
        );
    }

    #[test]
