    #[test]
    fn ws_codegen_auth_handler_injects_authorization_from_bearer_subproto() {
        // Wrapper with @authenticated should inject
        // `authorization: Bearer <token>` into the provider's map when
        // the client sends the token via subprotocol.
        let src = "type User { id: Int, name: Str, role: Str }\n\
                   @auth_provider\n\
                   fn check(h: Map<Str, Str>) -> Result<User> { return Err(\"x\") }\n\
                   @authenticated\n\
                   @ws(\"/chat\")\n\
                   async fn chat(conn: WsConn<Str>, user: User) -> Null { return null }";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // The provider block must contain the injection logic.
        assert!(
            code.contains("if let Some((_, ref __tok)) = __ws_bearer"),
            "expected Bearer injection branch in the auth wrapper"
        );
        assert!(
            code.contains("format!(\"Bearer {}\", __tok)"),
            "expected format!(`Bearer {{}}`, token) for the authorization header"
        );
    }

