    #[test]
    fn infer_param_int_from_call_site() {
        // `fn double(n) => n * 2` + `double(21)` → `n: Int` inferred.
        let src = "fn double(n) => n * 2\nprint(double(21))";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // The Rust signature of `double` must type `n: i64`.
        assert!(
            code.contains("fn double(n: i64)") || code.contains("fn double(mut n: i64)"),
            "expected `fn double(n: i64)` in the output (inference from Int call site)"
        );
    }

    #[test]
    fn infer_param_nominal_from_call_site() {
        // `fn greet(u) => "hola {u.name}"` + call with concrete User
        // now infers as `u: User` and emits the correct Rust
        // signature. Previously this case only worked on codegen
        // path #2 (resolve_param_type fallback); now path #1
        // (fill_inferred_param_types) covers it too, because
        // `type_to_type_expr` resolves `Nominal(id)` via TypeEnv.
        let src = "type User { id: Int, name: Str }\n\
                   fn greet(u) -> Str {\n\
                       return \"hola {u.name}\"\n\
                   }\n\
                   let ada = User { id: 1, name: \"Ada\" }\n\
                   print(greet(ada))";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // Rust signature with the nominal type (alias `User`).
        assert!(
            code.contains("fn greet(u: User)") || code.contains("fn greet(mut u: User)"),
            "expected `fn greet(u: User)` with inferred Nominal type"
        );
    }

    #[test]
    fn infer_param_multiple_call_sites() {
        // Multiple calls with the same type: the first call site
        // wins, the rest must be compatible (otherwise the checker fails).
        let src = "fn cuadrado(n) => n * n\n\
                   print(cuadrado(3))\n\
                   print(cuadrado(7))\n\
                   print(cuadrado(12))";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        assert!(code.contains("fn cuadrado(n: i64)") || code.contains("fn cuadrado(mut n: i64)"));
    }

    #[test]
    fn infer_param_str_from_call_site() {
        // Str case — `fn shout(s) => s.upper()` + call with Str literal.
        let src = "fn shout(s) -> Str {\n\
                       return s.upper()\n\
                   }\n\
                   print(shout(\"hola\"))";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen failed: {}", e));
        // Str → String in Rust.
        assert!(
            code.contains("fn shout(s: String)") || code.contains("fn shout(mut s: String)"),
            "expected `fn shout(s: String)` with inferred Str type"
        );
    }

    #[test]
    fn fill_inferred_param_types_resolves_nominal_via_typeenv() {
        // Path #1 — `fill_inferred_param_types` now resolves
        // `Type::Nominal(id)` to `TypeExpr::Named(canon_name)` using
        // the `TypeEnv`. Previously it returned None and path #1 left the
        // param unannotated (codegen path #2 still resolved it,
        // but the checker's re-check stayed without real annotation).
        use crate::lexer::tokenize;
        use crate::parser::parse;
        let src = "type User { id: Int, name: Str }\n\
                   fn greet(u) -> Str { return \"hola {u.name}\" }\n\
                   let ada = User { id: 1, name: \"Ada\" }\n\
                   print(greet(ada))";
        let tokens = tokenize(src).unwrap();
        let mut program = parse(tokens).unwrap();
        let (env, type_info, _defs, errs) = crate::types::check_program(&program);
        assert!(
            errs.is_empty(),
            "expected 0 checker errors, were {:?}",
            errs
        );
        fill_inferred_param_types(&mut program, &type_info, &env);
        // The `u` param of `greet` now has annotation TypeExpr::Named("User").
        let greet = program
            .iter()
            .find_map(|s| match s {
                Stmt::FnDef { name, params, .. } if name == "greet" => Some(params),
                _ => None,
            })
            .expect("fn greet in the program");
        let u_param = &greet[0];
        assert_eq!(u_param.name, "u");
        let te = u_param
            .type_
            .as_ref()
            .expect("type_ should be populated after fill_inferred");
        // Path #1 now covers Nominal: the TypeExpr is Named("User").
        match te {
            TypeExpr::Named(n) => assert_eq!(n, "User"),
            other => panic!("expected TypeExpr::Named(\"User\"), was {:?}", other),
        }
    }

