    #[test]
    fn codegen_orm_where_chain_emits_query_builder_and_terminal_all() {
        // 10.b.5 — `User.where(...).all(db)` now DOES compile: emits the
        // QueryBuilder constructor with the first WHERE fragment +
        // terminal `.all(&db)` inside an async block.
        let src = "@table(\"users\") type User {\n  \
                       @primary id: Int = 0\n  \
                       age: Int\n\
                   }\n\
                   async fn boot() -> Result<Null> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let _u = User.where(fn(u) => u.age > 18).all(db).await?\n  \
                       return Ok(null)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        assert!(
            rust.contains("__FitzQueryBuilder::<UserData>::new"),
            "expected the typed QueryBuilder constructor, was: {rust}",
        );
        assert!(
            rust.contains(".with_where(\"(\\\"age\\\" > $1)\""),
            "expected WHERE fragment translated from the closure, was: {rust}",
        );
        assert!(
            rust.contains("__FitzPgValue::Int(18i64)"),
            "expected parameterized binding of the Int literal, was: {rust}",
        );
        assert!(
            rust.contains(".all(&db"),
            "expected terminal .all(&db) in async block, was: {rust}",
        );
    }

    // ---- O1/O3 (v0.32.0) — SQL expressions + date arithmetic ----

    #[test]
    fn codegen_orm_update_inlines_db_now_and_raw_o1() {
        // O1 — `sql.now()` / `sql.raw("...")` in `.update` values inline
        // raw SQL in the SET clause (no `$N`). Ordering the SQL exprs
        // BEFORE the one real binding proves the placeholder-counter
        // migration: `last_status` must be `$1`, not `$3`.
        let src = "@table(\"monitors\") type Monitor {\n  \
                       @primary id: Int = 0\n  \
                       streak: Int\n  \
                       last_check_at: Str\n  \
                       last_status: Str\n\
                   }\n\
                   async fn boot() -> Result<Null> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let _ = Monitor.where(fn(m) => m.id == 1).update(db, {\"last_check_at\": sql.now(), \"streak\": sql.raw(\"streak + 1\"), \"last_status\": \"up\"}).await?\n  \
                       return Ok(null)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        assert!(
            rust.contains("\\\"last_check_at\\\" = NOW()"),
            "expected sql.now() inlined as NOW(), was: {rust}"
        );
        assert!(
            rust.contains("\\\"streak\\\" = streak + 1"),
            "expected sql.raw() inlined verbatim, was: {rust}"
        );
        assert!(
            rust.contains("\\\"last_status\\\" = $1"),
            "expected the only bound arg to be $1 (counter migration), was: {rust}"
        );
    }

    #[test]
    fn codegen_orm_where_date_arithmetic_and_db_now_o3() {
        // O3 — `m.field.plus_seconds(m.other) < sql.now()` translates to
        // `("field" + make_interval(secs => "other")) < NOW()`.
        let src = "@table(\"monitors\") type Monitor {\n  \
                       @primary id: Int = 0\n  \
                       last_check_at: Str\n  \
                       interval_secs: Int\n\
                   }\n\
                   async fn boot() -> Result<Null> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let _ = Monitor.where(fn(m) => m.last_check_at.plus_seconds(m.interval_secs) < sql.now()).all(db).await?\n  \
                       return Ok(null)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        assert!(
            rust.contains("make_interval(secs => \\\"interval_secs\\\")"),
            "expected make_interval date arithmetic, was: {rust}"
        );
        assert!(
            rust.contains("< NOW()"),
            "expected sql.now() → NOW() in the WHERE, was: {rust}"
        );
    }

    #[test]
    fn codegen_db_now_bare_call_errors_with_orm_hint() {
        // Bare `sql.now()` outside an ORM context has no representation.
        let src = "async fn boot() -> Result<Null> {\n  \
                       let _x = sql.now()\n  \
                       return Ok(null)\n\
                   }\n";
        let err = gen(src).expect_err("expected codegen error");
        assert!(
            err.to_string().contains(".update") || err.to_string().contains(".where"),
            "expected an ORM-context hint, was: {err:?}"
        );
    }

    // ---- Phase 10.b.4 — ORM write methods in codegen ----

    #[test]
    fn codegen_orm_insert_emits_insert_returning_with_cols_quoted() {
        // `User.insert(db, user)` emits `INSERT INTO "users"
        // ("id", "name", "age") VALUES ($1, $2, $3) RETURNING "id",
        // "name", "age"` with parameterized args read from the record.
        let src = "@table(\"users\") type User {\n  \
                       @primary id: Int = 0\n  \
                       name: Str\n  \
                       age: Int\n\
                   }\n\
                   async fn boot() -> Result<Null> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let u = User { id: 1, name: \"ada\", age: 30 }\n  \
                       let _inserted = User.insert(db, u).await?\n  \
                       return Ok(null)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        // SQL shape — INSERT INTO with cols and placeholders in type
        // declaration order. The r###...### raw literal uses `\"` which
        // ends up as `\"` literal in the generated Rust output.
        assert!(
            rust.contains("INSERT INTO \\\"users\\\" (\\\"id\\\", \\\"name\\\", \\\"age\\\") VALUES ($1, $2, $3) RETURNING \\\"id\\\", \\\"name\\\", \\\"age\\\""),
            "expected INSERT with cols + placeholders + quoted RETURNING, was: {rust}",
        );
        // Marshalling: __FitzPgValue::Int for id/age, ::Text for name.
        assert!(
            rust.contains("__FitzPgValue::Int(__g.id)"),
            "expected marshalling Int of field id, was: {rust}",
        );
        assert!(
            rust.contains("__FitzPgValue::Text(__g.name.clone())"),
            "expected marshalling Text of field name (with clone), was: {rust}",
        );
        assert!(
            rust.contains("__FitzPgValue::Int(__g.age)"),
            "expected marshalling Int of field age, was: {rust}",
        );
        // Deserialization with __FromFitzDbRow.
        assert!(
            rust.contains("<UserData as __FromFitzDbRow>::from_fitz_db_row"),
            "expected deserialization of RETURNING row via __FromFitzDbRow",
        );
        // No-rows fallback with insert-specific message.
        assert!(
            rust.contains("INSERT ... RETURNING returned no rows"),
            "expected clear fallback when RETURNING returns empty",
        );
    }

    #[test]
    fn codegen_orm_insert_pk_int_sentinel_zero_emits_runtime_branch() {
        // W4 (v0.10.6) — when there is `@primary id: Int`, codegen emits
        // a runtime branch `if __g.id == 0 { SQL_NO_PK } else { SQL_WITH_PK }`
        // so that Postgres assigns the id via bigserial when the user passes
        // `id: 0` as sentinel.
        let src = "@table(\"users\") type User {\n  \
                       @primary id: Int = 0\n  \
                       name: Str\n\
                   }\n\
                   async fn boot() -> Result<Null> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let u = User { id: 0, name: \"ada\" }\n  \
                       let _inserted = User.insert(db, u).await?\n  \
                       return Ok(null)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        // Runtime branch present: checks __g.id == 0 to decide SQL.
        assert!(
            rust.contains("if __g.id == 0"),
            "expected branch `if __g.id == 0` for sentinel skip, was: {rust}",
        );
        // SQL without PK (sentinel branch) — only (name) and placeholder $1.
        assert!(
            rust.contains("INSERT INTO \\\"users\\\" (\\\"name\\\") VALUES ($1) RETURNING"),
            "expected SQL without PK for sentinel branch, was: {rust}",
        );
        // SQL with PK (explicit branch) — (id, name) and placeholders $1, $2.
        assert!(
            rust.contains(
                "INSERT INTO \\\"users\\\" (\\\"id\\\", \\\"name\\\") VALUES ($1, $2) RETURNING"
            ),
            "expected SQL with PK for explicit branch, was: {rust}",
        );
        // RETURNING always includes all fields (does not depend on the branch).
        assert!(
            rust.contains("RETURNING \\\"id\\\", \\\"name\\\""),
            "expected RETURNING with id+name always, was: {rust}",
        );
    }

    #[test]
    fn codegen_orm_insert_without_primary_int_does_not_emit_runtime_branch() {
        // W4 — type without `@primary id: Int` (e.g. primary Str, or no
        // primary): the shape does NOT emit a branch — uses the single SQL as
        // before. Guarantees the non-bigserial path is not broken.
        let src = "@table(\"slugs\") type Slug {\n  \
                       @primary key: Str\n  \
                       value: Str\n\
                   }\n\
                   async fn boot() -> Result<Null> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let s = Slug { key: \"a\", value: \"b\" }\n  \
                       let _r = Slug.insert(db, s).await?\n  \
                       return Ok(null)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        assert!(
            !rust.contains("if __g.key == 0"),
            "did NOT expect branch on key Str — only applies to primary Int",
        );
        assert!(
            rust.contains(
                "INSERT INTO \\\"slugs\\\" (\\\"key\\\", \\\"value\\\") VALUES ($1, $2) RETURNING"
            ),
            "expected single SQL without branch, was: {rust}",
        );
    }

    #[test]
    fn codegen_orm_insert_respects_column_name_override() {
        // `@column(name="sql_name")` must be used in col_list, RETURNING,
        // and NOT in the field accessor (`__g.<fitz_name>`).
        let src = "@table(\"events\") type Event {\n  \
                       @primary id: Int = 0\n  \
                       @column(name=\"event_kind\") kind: Str\n\
                   }\n\
                   async fn boot() -> Result<Null> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let e = Event { id: 1, kind: \"login\" }\n  \
                       let _r = Event.insert(db, e).await?\n  \
                       return Ok(null)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        // Col list and RETURNING use the SQL name override.
        assert!(
            rust.contains("INSERT INTO \\\"events\\\" (\\\"id\\\", \\\"event_kind\\\")"),
            "expected col list with `event_kind` override, was: {rust}",
        );
        assert!(
            rust.contains("RETURNING \\\"id\\\", \\\"event_kind\\\""),
            "expected RETURNING with `event_kind` override, was: {rust}",
        );
        // But the field accessor is still the Fitz name (`kind`),
        // not the SQL one (`event_kind`).
        assert!(
            rust.contains("__g.kind.clone()"),
            "expected accessor `__g.kind.clone()` (Fitz name), was: {rust}",
        );
        assert!(
            !rust.contains("__g.event_kind"),
            "did NOT expect accessor by SQL name `__g.event_kind`",
        );
    }

    #[test]
    fn codegen_orm_insert_marshals_nullable_as_option_match() {
        // `Nullable<T>` is emitted as `match field { Some(v) => ...,
        // None => __FitzPgValue::Null }` parallel to `Value::Null` in the
        // evaluator.
        let src = "@table(\"posts\") type Post {\n  \
                       @primary id: Int = 0\n  \
                       title: Str\n  \
                       subtitle: Str?\n\
                   }\n\
                   async fn boot() -> Result<Null> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let p = Post { id: 1, title: \"hola\", subtitle: null }\n  \
                       let _r = Post.insert(db, p).await?\n  \
                       return Ok(null)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        // The nullable field is emitted with a Some/None match.
        assert!(
            rust.contains("match __g.subtitle.clone()"),
            "expected `match __g.subtitle.clone()` for nullable field, was: {rust}",
        );
        assert!(
            rust.contains("Some(__some_v) => __FitzPgValue::Text(__some_v)"),
            "expected Some arm wrapping the inner in Text, was: {rust}",
        );
        assert!(
            rust.contains("None => __FitzPgValue::Null"),
            "expected None arm mapping to __FitzPgValue::Null, was: {rust}",
        );
    }

    #[test]
    fn codegen_orm_update_and_delete_without_where_aborts_with_safety_message() {
        // 10.b.5 — dispatch on `Type.update(...)` / `Type.delete(...)`
        // WITHOUT prior `.where(...)` is rejected in codegen with a message
        // parallel to the evaluator's safety guard (would affect the whole
        // table).
        let src_update = "@table(\"users\") type User {\n  \
                            @primary id: Int = 0\n  \
                            name: Str\n\
                        }\n\
                        async fn boot() -> Result<Null> {\n  \
                            let db = db.connect(\"postgres://x@h/d\").await?\n  \
                            let _n = User.update(db, {\"name\": \"ada\"}).await?\n  \
                            return Ok(null)\n\
                        }\n";
        let err_u = gen(src_update).expect_err("expected error de codegen");
        assert!(
            err_u.message.contains("requires a prior `.where(...)`")
                && err_u.message.contains("User.update"),
            "expected mention of safety guard for `User.update`, was: {}",
            err_u.message
        );
        let src_delete = "@table(\"users\") type User {\n  \
                            @primary id: Int = 0\n  \
                            name: Str\n\
                        }\n\
                        async fn boot() -> Result<Null> {\n  \
                            let db = db.connect(\"postgres://x@h/d\").await?\n  \
                            let _n = User.delete(db).await?\n  \
                            return Ok(null)\n\
                        }\n";
        let err_d = gen(src_delete).expect_err("expected codegen error");
        assert!(
            err_d.message.contains("requires a prior `.where(...)`")
                && err_d.message.contains("User.delete"),
            "expected mention of safety guard for `User.delete`, was: {}",
            err_d.message
        );
    }

