    #[test]
    fn codegen_orm_chain_of_3_methods_emits_complete_with_chain() {
        // `User.where(f).limit(10).all(db)` emits three calls
        // chained on the QueryBuilder + terminal `.all(&db)`.
        let src = "@table(\"users\") type User {\n  \
                       @primary id: Int = 0\n  \
                       age: Int\n\
                   }\n\
                   async fn boot() -> Result<Null> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let _u = User.where(fn(u) => u.age > 18).limit(10).all(db).await?\n  \
                       return Ok(null)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        assert!(
            rust.contains("__FitzQueryBuilder::<UserData>::new"),
            "expected QB constructor, was: {rust}",
        );
        assert!(
            rust.contains(".with_where("),
            "expected .with_where(...) in the chain, was: {rust}",
        );
        assert!(
            rust.contains(".with_limit(10i64)"),
            "expected .with_limit(10i64) in the chain, was: {rust}",
        );
        assert!(
            rust.contains(".all(&db"),
            "expected terminal .all(&db), was: {rust}",
        );
    }

    #[test]
    fn codegen_orm_multiple_wheres_combine_with_and_and_renumber() {
        // Two consecutive `.where(...)`: the second combines with
        // AND via `with_where`. The runtime renumbers the fragment's
        // placeholders so they follow the first where. Codegen does NOT
        // pre-renumber — the static syntax always emits `$1`, and
        // the `with_where` helper fixes them at runtime.
        let src = "@table(\"users\") type User {\n  \
                       @primary id: Int = 0\n  \
                       age: Int\n  \
                       name: Str\n\
                   }\n\
                   async fn boot() -> Result<Null> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let _u = User.where(fn(u) => u.age > 18).where(fn(u) => u.name == \"ada\").all(db).await?\n  \
                       return Ok(null)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        // Two calls to with_where, in that order.
        let n = rust.matches(".with_where(").count();
        assert_eq!(
            n, 2,
            "expected 2 `.with_where(...)` in the chain, was {n}: {rust}"
        );
        // The second fragment uses `$1` (relative to its own scope) —
        // the renumber to `$2` happens at runtime with
        // `__fitz_qb_renumber_placeholders`.
        assert!(
            rust.contains("(\\\"name\\\" = $1)"),
            "expected `\"name\" = $1` in the second fragment (no renumber in codegen), was: {rust}",
        );
    }

