    #[test]
    fn codegen_orm_list_int_field_emits_array_int8_in_insert() {
        // Field `tags: List<Int>` must emit:
        //   - deserialize: match on __FitzPgValue::Array, iterate and
        //     coerce each item with __fitz_pg_to_i64.
        //   - insert: SQL placeholder `$N::int8[]` + accessor that
        //     builds __FitzPgValue::Array { elem_oid: INT8, ... }.
        let src = "@table(\"items\") type Item {\n  \
                       @primary id: Int = 0\n  \
                       tags: List<Int>\n\
                   }\n\
                   async fn boot() -> Result<Item> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let it = Item.insert(db, Item { id: 0, tags: [1, 2, 3] }).await?\n  \
                       return Ok(it)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        // SQL cast in INSERT placeholders.
        assert!(
            rust.contains("::int8[]"),
            "expected `::int8[]` suffix in INSERT placeholder, was: {rust}",
        );
        // Array construction in marshal.
        assert!(
            rust.contains("__fitz_db_runtime::oid::INT8"),
            "expected reference to oid::INT8, was: {rust}",
        );
        // Deserialize iterator (in item's __FromFitzDbRow).
        assert!(
            rust.contains("__fitz_pg_to_i64"),
            "expected use of __fitz_pg_to_i64 to coerce array items, was: {rust}",
        );
    }

