    // ---- Phase 10.b.15 — Eager loading (.preload over HasMany) ----

    #[test]
    fn codegen_preload_emits_with_preload_and_static_dispatch() {
        // `User.preload("posts").all(db)` must emit the wrapper
        // with .with_preload("posts") + the static dispatch that
        // executes the batch + populate.
        let src = "@table type Post {\n  \
                       @primary id: Int = 0\n  \
                       user_id: Int\n\
                   }\n\
                   @table type User {\n  \
                       @primary id: Int = 0\n  \
                       @has_many(\"Post\") posts: List<Post>\n\
                   }\n\
                   async fn boot() -> Result<List<User>> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       return User.preload(\"posts\").all(db).await\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        assert!(
            rust.contains(".with_preload(\"posts\")"),
            "expected .with_preload(\"posts\") in the chain, was: {rust}",
        );
        // The static dispatch must be present with the "posts" branch.
        assert!(
            rust.contains("\"posts\" =>") && rust.contains("__preloads.iter()"),
            "expected static dispatch with branch for `posts`, was: {rust}",
        );
        // Target (Post) batch query with `WHERE \"user_id\" IN (...)`.
        assert!(
            rust.contains("FROM \\\"post\\\"") && rust.contains("\\\"user_id\\\" IN"),
            "expected batch query with FROM post + WHERE user_id IN, was: {rust}",
        );
    }

