    // ---- Phase 10.b.13.a — Navigation chain (without db = QueryBuilder) ----

    #[test]
    fn codegen_navigation_without_db_returns_query_builder() {
        // `user.posts()` (no args) must emit a QueryBuilder<Post>
        // with the implicit WHERE already applied. Type: QueryBuilder<Post>,
        // not Future<...>. Without enveloping async block.
        let src = "@table type Post {\n  \
                       @primary id: Int = 0\n  \
                       user_id: Int\n\
                   }\n\
                   @table type User {\n  \
                       @primary id: Int = 0\n  \
                       @has_many(\"Post\") posts: List<Post>\n\
                   }\n\
                   async fn boot() -> Result<List<Post>> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let u = User.where(fn(u) => u.id == 1).first(db).await?\n  \
                       let xs = u.posts().all(db).await?\n  \
                       return Ok(xs)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        // The QB branch has `__nav_fk`/`__nav_pg` + with_where
        // without async block or automatic terminal.
        assert!(
            rust.contains("__nav_fk") && rust.contains("__nav_pg") && rust.contains(".with_where("),
            "expected helpers __nav_* + .with_where, was: {rust}",
        );
    }

    #[test]
    fn codegen_navigation_full_chain_compiles() {
        // `u.posts().where(...).limit(5).all(db).await?` chain of
        // 4 ops on the QB returned by navigation.
        let src = "@table type Post {\n  \
                       @primary id: Int = 0\n  \
                       title: Str\n  \
                       user_id: Int\n\
                   }\n\
                   @table type User {\n  \
                       @primary id: Int = 0\n  \
                       @has_many(\"Post\") posts: List<Post>\n\
                   }\n\
                   async fn boot() -> Result<List<Post>> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let u = User.where(fn(u) => u.id == 1).first(db).await?\n  \
                       let xs = u.posts().where(fn(p) => p.title.starts_with(\"a\")).limit(5).all(db).await?\n  \
                       return Ok(xs)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        // Multiple with_where (one implicit from nav + one explicit
        // from chain) + with_limit.
        assert!(
            rust.matches(".with_where(").count() >= 2,
            "expected 2+ with_where (implicit nav + explicit chain), was: {rust}",
        );
        assert!(
            rust.contains(".with_limit(5i64)"),
            "expected .with_limit(5i64), was: {rust}",
        );
    }

