    #[test]
    fn codegen_navigation_more_than_one_arg_aborts() {
        // The checker rejects BEFORE codegen (arity check
        // in infer_method_call ~3745). We use `gen_no_check` to
        // skip the checker and test the codegen error itself.
        let src = "@table type Post {\n  \
                       @primary id: Int = 0\n  \
                       user_id: Int\n\
                   }\n\
                   @table type User {\n  \
                       @primary id: Int = 0\n  \
                       @has_many(\"Post\") posts: List<Post>\n\
                   }\n\
                   async fn boot() -> Result<Null> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let u = User.where(fn(u) => u.id == 1).first(db).await?\n  \
                       let _ = u.posts(db, db).await?\n  \
                       return Ok(null)\n\
                   }\n";
        // We look for the checker error (which fires first).
        let tokens = crate::lexer::tokenize(src).expect("lex OK");
        let program = crate::parser::parse(tokens).expect("parse OK");
        let (_env, _types, _defs, errors) = crate::types::check_program(&program);
        assert!(
            errors
                .iter()
                .any(|e| e.message.contains("posts(db?)") && e.message.contains("received 2")),
            "expected checker error about navigation arity, errors: {:?}",
            errors
        );
    }

    // ---- Phase 10.b.12.b — Concrete Map<Str, T> (typed JSONB) ----

    #[test]
    fn codegen_orm_concrete_map_str_int_emits_deserialize_and_marshal() {
        // Field `counts: Map<Str, Int>` must emit:
        //   - struct field types Arc<Mutex<Vec<(String, i64)>>>.
        //   - deserialize: serde_json::from_str of the Text + iter on
        //     Object + validate each value is as_i64().
        //   - marshal: iter on the Vec + build serde_json::Map
        //     with Number((*v).into()) + to_string.
        //   - SQL cast: ::jsonb.
        let src = "@table(\"docs\") type Doc {\n  \
                       @primary id: Int = 0\n  \
                       counts: Map<Str, Int>\n\
                   }\n\
                   async fn boot() -> Result<List<Doc>> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       return Doc.all(db).await\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        // Struct field type.
        assert!(
            rust.contains("Vec<(String, i64)>") || rust.contains("Vec < (String , i64) >"),
            "expected Vec<(String, i64)> for counts, was: {rust}",
        );
        // Deserialize: serde_json parse + as_i64.
        assert!(
            rust.contains("serde_json::from_str") && rust.contains("as_i64()"),
            "expected deserialize via serde_json + as_i64, was: {rust}",
        );
    }

    #[test]
    fn codegen_orm_concrete_map_str_str_compiles_and_insert_marshals() {
        let src = "@table(\"docs\") type Doc {\n  \
                       @primary id: Int = 0\n  \
                       attrs: Map<Str, Str>\n\
                   }\n\
                   async fn boot() -> Result<Doc> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let d = Doc.insert(db, Doc { id: 0, attrs: {\"k\": \"v\"} }).await?\n  \
                       return Ok(d)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        // Marshal: construct with serde_json::Value::String.
        assert!(
            rust.contains("serde_json::Value::String"),
            "expected construct String of marshal, was: {rust}",
        );
        // SQL cast ::jsonb also for concrete Map<Str, T>.
        assert!(
            rust.contains("::jsonb"),
            "expected ::jsonb cast for concrete Map<Str, T>, was: {rust}",
        );
    }

